/* ---------- GRIMOIRE: the reference entries ----------
   Dennis's request (10/22/2026): every term in and around the interface, with what it means and how
   it reads in a game, in analysis and inside the engine. One entry per term: id (kebab case, used
   by data-term attributes and "see" links), term (as the interface shows it), aka (other names and
   spellings, for search), cat (rules, notation, tactics, eval, engine, analysis, testing,
   interface), def, the three viewpoints game / analysis / engine (each optional, never padding),
   where (where it is in MONOLITH), go (a tab that shows it), example, see (related ids). Plain text
   throughout. Read by the Grimoire tab and the term cards. */
const GRIMOIRE = [
  {"id": "legal-move", "term": "Legal move", "aka": ["legal moves", "legal", "move generation"], "cat": "rules", "def": "A move the rules allow in the position: the piece moves as it may, and the mover's own king is not left in check.", "game": "Select a piece and its legal squares light up: a dot for a quiet move, a ring for a capture. A square that does not light up cannot be played, even if the piece could normally go there; usually the move would expose your king.", "analysis": "Every count in Analyze is over legal moves only: the root move-value field scores each legal move once, and the Sharpness note says how many of them stay within 5 % of the best.", "engine": "Stockfish generates pseudo-legal moves and filters those that leave its king attacked; the page runs its own generator for the board and checks it against known move counts (perft).", "where": "Play and every board you can move on. Show legal moves (Settings, Board, or :legal) turns the dots and rings on or off. Position, Read: the moves of each side, as bars (point at one to light the squares).", "go": "settings", "example": "The starting position has 20 legal moves for each side: 16 pawn moves and 4 knight moves.", "see": ["check", "perft", "castling", "en-passant"]},
  {"id": "check", "term": "Check", "aka": ["in check", "+"], "cat": "rules", "def": "A king is in check when an enemy piece attacks it. The side in check must answer at once: move the king, capture the checker, or block the line.", "game": "The king's square glows red and the board gives a short shudder. The turn card says your king is in check, and the Coach counts how many moves get you out.", "analysis": "A check in an engine line forces the reply, so lines full of checks are short and concrete. SAN marks a checking move with +.", "engine": "Stockfish searches checks and evasions specially: it extends the search when a move gives check, and in check it generates only the evasions.", "where": "Play: the red square, the turn card and the Coach's watch note. In SAN: the + after a move.", "go": "play", "example": "1. e4 f5 2. Qh5+ : the queen checks along the diagonal h5–e8, and g6 is the only legal answer.", "see": ["checkmate", "double-check", "san", "legal-move"]},
  {"id": "checkmate", "term": "Checkmate", "aka": ["mate", "#", "mated"], "cat": "rules", "def": "Check with no legal answer. The game ends at once and the side that gave mate wins.", "game": "The losing king topples, the winner is crowned, and the result card says who won. The Coach names the pattern when it knows it (back rank, smothered).", "analysis": "A forced mate shows as #n from White's view in Analyze (#3, or #−3 when Black mates), and as +M3 or −M3 on the evaluation bar in Play. A mate score outranks any material count.", "engine": "The engine reports mate in moves, not plies: score mate 3 means three of the mover's own moves, negative when the mover is the one being mated.", "where": "Play: the result card and the ceremony. Analyze: #n in the line table. The Coach's grades treat a mate found, missed or allowed by lichess's rules.", "go": "play", "example": "1. e4 e5 2. Bc4 Nc6 3. Qh5 Nf6 4. Qxf7# , the four-move mate.", "see": ["check", "mate-score", "stalemate", "coach-grades"]},
  {"id": "stalemate", "term": "Stalemate", "aka": ["stalemated"], "cat": "rules", "def": "The side to move is not in check and has no legal move. The game is drawn, whatever the material.", "game": "Both kings bow and the result card reads \"Stalemate. The game is drawn.\" When you are winning and the other side is almost out of moves, the Coach warns you if one of your moves would stalemate, so you can leave the king a square.", "analysis": "A stalemate scores 0.00. Endgames with a lone king are where it hides: a queen move that takes the last square without giving check throws the win away.", "engine": "The engine sees stalemate as a position with no legal moves and no check, scored as a draw, so it avoids it when ahead and steers into it when behind.", "where": "Play: the result card, and the Coach's watch note (\"Careful: ... has almost no moves left\").", "go": "position", "example": "Black king a1, white queen b3, white king h8, White to move: almost any quiet move, such as Kg7, is stalemate.", "see": ["draw", "checkmate", "endgame", "coach"]},
  {"id": "castling", "term": "Castling", "aka": ["castle", "O-O", "O-O-O", "0-0", "kingside", "queenside"], "cat": "rules", "def": "One move of king and rook: the king goes two squares toward a rook and the rook jumps over it. Neither may have moved, the squares between must be empty, and the king may not be in check, pass through check or land in check.", "game": "When castling is legal, the chip on the board names the squares (for example \"Castle: g1 or the h1 rook for O-O\") and lanes mark the path. Click the king, then its target square or the rook, or drag the king there. Typed, it is O-O, O-O-O, 0-0, or the king's move e1g1 (e1h1 works too).", "analysis": "Castling rights are part of the position: in FEN they are the KQkq field. Two positions with the same pieces but different rights are different positions, for repetition and for the opening book.", "engine": "In UCI the move is sent as the king's two-square move, e1g1 or e1c1. Losing the right to castle is part of the engine's king-safety evaluation.", "where": "Play: the castling chip, lanes and rook click-through. Position, Read: the castling rights as badges. Position, Set up: the castling toggles and the castling field of the FEN. Position, Studies: the Castling drill (Set-ups).", "go": "position", "example": "Castling drill (Position, Studies): both sides can castle either way, and you move both. O-O puts the white king on g1 and the rook on f1.", "see": ["king-safety", "castling-notation", "fen", "development"]},
  {"id": "en-passant", "term": "En passant", "aka": ["e.p.", "ep", "in passing"], "cat": "rules", "def": "A pawn that advances two squares and lands beside an enemy pawn may be captured as if it had moved one: the capturing pawn goes to the square it skipped. Only on the very next move.", "game": "When it is available, the empty square behind the pawn lights up as a capture. Wait one move and the chance is gone.", "analysis": "FEN records the skipped square after any two-square pawn move. The page counts it only when a capture is actually legal, so a position does not count as new for repetition, or miss its opening name, because of an en passant square nobody can use.", "engine": "The engine receives the en passant square through the FEN or the move list and treats the capture like any other.", "where": "Play and every board you can move on. Position, Read: the en passant badge. Position, Set up: the en passant choice and the en passant field of the FEN.", "go": "position", "example": "1. e4 Nf6 2. e5 d5 3. exd6 : White takes the d5 pawn en passant; the pawn lands on d6.", "see": ["fen", "threefold-repetition", "legal-move", "san"]},
  {"id": "promotion", "term": "Promotion", "aka": ["promote", "queening", "underpromotion", "=Q"], "cat": "rules", "def": "A pawn reaching the last rank becomes a queen, rook, bishop or knight of its own colour, at once and as part of the same move.", "game": "When your pawn arrives, a bar asks for Queen, Rook, Bishop or Knight, and the new piece flashes in. Typed, add the piece letter: e7e8q, or e8=Q in SAN; without a letter, a typed e7e8 becomes a queen.", "analysis": "Underpromotion (to a knight, say) is rare and almost always tactical: a knight that checks, or a rook that avoids stalemate. The Coach points it out when it happens.", "engine": "UCI writes the promotion piece as a fifth letter in lower case: e7e8q, a7a8n.", "where": "Play: the promotion bar. The move field under the move list.", "go": "play", "example": "A white pawn on b7 plays b8=Q, or b8=N+ when a knight check wins more.", "see": ["san", "long-algebraic", "endgame", "material"]},
  {"id": "draw", "term": "Draw", "aka": ["drawn", "1/2", "half a point", "Draw agreed", "offer a draw", ":draw"], "cat": "rules", "def": "A game that ends with neither side winning: each scores half a point. Stalemate, insufficient material, the fifty-move rule and threefold repetition end it on their own.", "game": "Both kings bow, and the result card names the reason. A draw can also be agreed. Between two players on one screen, Draw offers it for the side to move, and the other side agrees or plays on. Against the computer, offer it on your turn: Stockfish judges the position at full strength, whatever its level, and accepts when it stands a pawn or more worse or faces mate, or from move 20 when the position is level. Otherwise it plays on, and you can offer again five moves later.", "analysis": "An engine score near 0.00, or a WDL with a large middle band, means a draw is the likeliest result with best play.", "engine": "The engine scores a forced draw as exactly 0 and, with WDL on, reports the draw chance per mille.", "where": "Play: the result card, and Draw beside New game and Resign during a game. Palette: :draw. Crucible: draws by repetition, insufficient material, the fifty-move rule, and adjudicated draws.", "go": "play", "example": "Crucible, recorded run: 30 of the 90 games are draws, 15 of them by threefold repetition.", "see": ["stalemate", "threefold-repetition", "fifty-move-rule", "insufficient-material", "wdl"]},
  {"id": "fifty-move-rule", "term": "Fifty-move rule", "aka": ["50-move rule", "halfmove clock", "fifty moves"], "cat": "rules", "def": "Fifty moves by each side, a hundred plies, with no capture and no pawn move, and the game is drawn.", "game": "Here the draw is automatic at a hundred plies (over the board, FIDE lets a player claim it then, and ends the game itself at seventy-five moves). From forty moves without a capture or pawn move, the Coach counts down the moves left.", "analysis": "The count matters in long endgames: a winning line that needs more than the remaining moves wins nothing. A capture or a pawn move resets it.", "engine": "FEN's fifth field is the halfmove clock; the engine uses it to score positions near the limit as drawn.", "where": "Play: the result card and the Coach's countdown. Position, Read: the fifty-move bar. Position, Set up: the halfmove clock in the FEN.", "go": "position", "example": "A FEN ending in 85 60 has fifteen plies left: the Coach says 8 moves left before the fifty-move rule.", "see": ["draw", "fen", "ply", "endgame"]},
  {"id": "threefold-repetition", "term": "Threefold repetition", "aka": ["repetition", "threefold", "perpetual"], "cat": "rules", "def": "The same position, with the same side to move, the same castling rights and the same en passant chance, appears for the third time. The game is drawn.", "game": "The draw is automatic here at the third time. When a position appears for the second time and one side is clearly better, the Coach says so: change course if you are the one who is better.", "analysis": "Repetition is the defender's resource: a perpetual check repeats the position until it is a draw. Positions are only compared since the last capture or pawn move, which no repetition can cross.", "engine": "Stockfish scores a repetition inside its search as a draw, so a losing side heads for one and a winning side steers clear.", "where": "Play: the result card and the Coach's watch note. Crucible: a game termination, 15 times in the recorded run. Position, Read: Rules, Repetition.", "go": "play", "example": "1. Nf3 Nf6 2. Ng1 Ng8 3. Nf3 Nf6 4. Ng1 Ng8 : the starting position for the third time, a draw.", "see": ["draw", "en-passant", "castling", "coach"]},
  {"id": "insufficient-material", "term": "Insufficient material", "aka": ["dead draw", "not enough material"], "cat": "rules", "def": "Neither side has enough left to give mate by any series of legal moves. The game is drawn.", "game": "The page ends the game for king against king, king and one minor piece against king, and king and bishop against king and bishop with both bishops on squares of the same colour. King and two knights against king plays on: mate is possible if the defender helps.", "analysis": "Material that cannot mate is worth nothing, however many pawns of value it holds: a bishop and the wrong rook's pawn is a famous example, though the page only ends the clear cases above.", "engine": "The engine evaluates these endings as dead draws and does not rely on the rule to stop.", "where": "Play: the result card. Crucible: a game termination, 4 times in the recorded run.", "go": "play", "example": "White king and bishop on c1 against Black king and bishop on f8: both bishops on dark squares, so the game is drawn at once.", "see": ["draw", "dead-position", "material", "endgame"]},
  {"id": "dead-position", "term": "Dead position", "aka": ["dead"], "cat": "rules", "def": "A position in which no series of legal moves can end in mate for either side. FIDE's rules end the game as a draw there.", "game": "The page recognises the insufficient-material cases only. Other dead positions, such as a locked pawn wall with kings that cannot get through, play on until repetition or the fifty-move rule ends them.", "analysis": "A score pinned at 0.00 while both sides shuffle is often a dead or fortress position.", "engine": "Stockfish does not prove positions dead; it scores them near 0.00 because its search finds nothing better.", "where": "Every game: insufficient material ends the game, other dead positions do not.", "see": ["insufficient-material", "draw", "fifty-move-rule"]},
  {"id": "resignation", "term": "Resignation", "aka": ["resign", "resigns"], "cat": "rules", "def": "A player ends the game by conceding it. The opponent wins.", "game": "Resign sits beside New game under the Play panel's cards and asks once before it acts. Against the computer you resign for yourself; in a friend game, for the side to move. The Coach then reviews the game like any other ending.", "analysis": "Resigning early in a lost position saves time; a review afterwards shows where it was lost.", "where": "Play: the Resign button under the cards. Palette: :resign.", "go": "play", "example": "\"Obsidian resigns. Marble wins.\"", "see": ["draw", "checkmate", "coach"]},
  {"id": "ply", "term": "Ply", "aka": ["plies", "half-move", "halfmove"], "cat": "rules", "def": "One move by one side. A full move is two plies, White's and Black's.", "game": "The move list counts full moves; the review and the heartbeat step ply by ply.", "analysis": "Depths and walks are measured in plies: the fork walk covers the first eight plies of line 1, and the Synaptic PV labels each chip by its ply.", "engine": "Search depth is counted in plies: depth 20 looks ten moves ahead for each side along the main line, further along forcing lines.", "where": "Analyze: the Synaptic PV and the fork walk. Crucible: the heartbeat has a slot for every ply; adjudication counts plies.", "go": "analyze", "example": "After 1. e4 e5 2. Nf3, the game is three plies old.", "see": ["move-number", "depth", "fork-walk", "heartbeat"]},
  {"id": "move-number", "term": "Move number", "aka": ["fullmove", "move"], "cat": "rules", "def": "The count of full moves, starting at 1 and rising after each of Black's moves.", "game": "The turn card shows the move you are on, and so does the match strip in the app bar, beside whose turn it is.", "analysis": "SAN writes the move number before White's move (12. Nf3) and an ellipsis before Black's when White's is not shown (12… Nf6).", "engine": "The engine ignores the move number; it is only FEN's sixth field.", "where": "Play: the Move chip on the turn card, the match strip, the move list.", "go": "play", "example": "The Reference FEN ends w - - 0 25: White is about to play move 25.", "see": ["ply", "move-ellipsis", "fen", "side-to-move"]},
  {"id": "side-to-move", "term": "Side to move", "aka": ["turn", "to move", "stm"], "cat": "rules", "def": "Whose turn it is. Part of the position: the same pieces with the other side to move is a different position.", "game": "The turn card and the match strip say who moves; the avatar is marble or obsidian.", "analysis": "Engines report scores from the side to move. The page turns every score to White's view, so +1.00 always favours White wherever you read it.", "engine": "UCI score cp 50 means the mover is half a pawn better. The Coach's threat search hands the move to the opponent (a null move) to ask what it would do.", "where": "Play: the turn card. Position, Read: the side marked to move. Position, Set up: White to move or Black to move, the second field of the FEN (w or b).", "go": "play", "example": "A FEN with b after the board: Black to move.", "see": ["white-view", "fen", "evaluation", "move-number"]},
  {"id": "ranks-and-files", "term": "Ranks and files", "aka": ["rank", "file", "coordinates", "a-h", "1-8"], "cat": "rules", "def": "Files are the columns a to h, from White's left; ranks are the rows 1 to 8, from White's side. Every square has a name: e4 is the e-file, fourth rank.", "game": "Board coordinates (Settings, Board) prints the files and ranks on the frame. They stay correct when you flip the board.", "analysis": "Open files, the seventh rank and the long diagonal are named by their squares; the Coach speaks this way (\"a rook on the open file\").", "engine": "UCI moves are written square to square: e2e4.", "where": "The board's frame (Settings, Board: Board coordinates; palette :coords). Every notation in the app.", "go": "settings", "example": "The squares a1 and h8 are dark in the corners of every board; h1 is light, \"light on the right\".", "see": ["san", "long-algebraic", "flip-board"]},
  {"id": "san", "term": "SAN", "aka": ["standard algebraic notation", "algebraic notation", "short algebraic"], "cat": "notation", "def": "Standard Algebraic Notation: the piece letter (K, Q, R, B, N; none for a pawn), x for a capture, the target square, =Q for a promotion, + for check and # for mate. A second letter or digit tells two like pieces apart.", "game": "The move list, the Coach and the match strip all use SAN. You can type SAN in the move field: Nf3, exd5, e8=Q, O-O.", "analysis": "Engine lines are shown in SAN, converted from the engine's UCI moves move by move.", "engine": "Engines do not speak SAN; UCI uses long algebraic. The page converts both ways.", "where": "The move list, the Coach, the line tables, the move field.", "example": "Nbd7: the knight from the b-file to d7, because the other knight could go there too.", "see": ["long-algebraic", "castling-notation", "annotation-symbols", "move-ellipsis"]},
  {"id": "long-algebraic", "term": "Long algebraic", "aka": ["UCI notation", "LAN", "coordinate notation", "e2e4"], "cat": "notation", "def": "A move written as its start and end squares, with a promotion letter when needed: e2e4, g1f3, e7e8q.", "game": "The move field accepts it: type e2e4 and press Play. For castling, the king's move (e1g1) or the king onto its rook (e1h1) both work.", "analysis": "Recorded data files keep moves in this form beside SAN, because it needs no position to read.", "engine": "This is the engine's language: UCI receives the game as position startpos moves e2e4 e7e5 and answers bestmove g1f3.", "where": "The move field under the move list; the UCI traffic between page and engine.", "example": "e7e8n promotes to a knight on e8.", "see": ["san", "uci", "bestmove", "promotion"]},
  {"id": "fen", "term": "FEN", "aka": ["Forsyth-Edwards Notation", "position string"], "cat": "notation", "def": "One line that describes a position: the pieces rank by rank from the eighth, the side to move, castling rights, the en passant square, the halfmove clock and the move number.", "game": "The Set up view of the Position tab shows the FEN of the board you see, each of its six fields in its own colour, with a chip per field under the box: select one to have it read out, including what the page quietly corrects (a castling right the board cannot have, an en passant square that does not fit). Paste or edit a FEN and the board above it follows; build on the board and the FEN follows. Who plays it chooses the game Play this position starts from it (against Stockfish, on either side, or both sides on this screen); Copy FEN copies it.", "analysis": "A FEN is how a position travels: from a book or another site into Analyze, whose Load section analyses it where it is. The palette's :fen opens one in Set up; in Analyze it is analysed there.", "engine": "The page sends the engine position fen ... (or startpos with moves) before every search.", "where": "Position, Set up. Position, Read: Copy FEN and Edit in Set up. Analyze: Load. Play: Copy FEN (in a game) and Load a game (on the setup). Palette: :fen, :copy fen.", "go": "position", "example": "rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR b KQkq e3 0 1 is the position after 1. e4. The page writes the skipped square e3, as the FEN standard does; it only counts when a capture there is legal.", "see": ["side-to-move", "castling", "en-passant", "fifty-move-rule", "pgn"]},
  {"id": "pgn", "term": "PGN", "aka": ["Portable Game Notation", "Copy PGN", "Download PGN", "Load a game", ":copy pgn", ":load pgn"], "cat": "notation", "def": "Portable Game Notation: the standard text format for whole games, with header tags (players, event, result) and the moves in SAN.", "game": "Copy PGN and Download PGN, under New game and Resign, write the game on screen: the seven tags (with SetUp and FEN for a game begun part-way), the moves and the result. In a two-player game, a move played after its side used Analyze is followed by a comment that says so, such as {Marble used Analyze before this move}. Load a game, on the Play setup, reads a pasted PGN, or a FEN, and plays on from its last move with the choices above it; a move that is not legal is named.", "analysis": "Analyze's Load takes a PGN game too: it opens at the last position with the moves in the list, both sides moved by hand. The Crucible's Copy results JSON keeps every game's moves in SAN, so they can be turned into PGN elsewhere.", "where": "Play: Copy PGN, Download PGN and Copy FEN (in a game); Load a game (on the setup). Analyze: Load. Palette: :copy pgn, :download pgn, :load pgn.", "go": "play", "see": ["fen", "san", "results-json"]},
  {"id": "castling-notation", "term": "Castling notation", "aka": ["O-O", "O-O-O", "0-0", "0-0-0"], "cat": "notation", "def": "O-O is castling on the king's side, O-O-O on the queen's side. Some write zeros instead of the letter O.", "game": "Typed in the move field, O-O and 0-0 both work, as do the king's move (e1g1) and the king onto its rook (e1h1).", "engine": "UCI sends castling as the king's move: e1g1, e1c1, e8g8, e8c8.", "where": "The move list and the move field.", "example": "O-O-O+ : queenside castling that gives check with the rook on d1 or d8.", "see": ["castling", "san", "long-algebraic"]},
  {"id": "move-ellipsis", "term": "Move ellipsis", "aka": ["…", "...", "Black's move"], "cat": "notation", "def": "Three dots after a move number mark Black's move when White's is not written beside it: 24… cxd4.", "game": "The Coach heads each note with the move, so Black's moves read 12… Nf6.", "analysis": "Engine lines that start with Black to move begin with the ellipsis: 24… cxd4 25. Re7+.", "where": "The Coach, the line tables, the Synaptic PV.", "example": "3… Nf6 is Black's third move.", "see": ["san", "move-number"]},
  {"id": "annotation-symbols", "term": "Annotation symbols", "aka": ["!!", "!", "!?", "?!", "?", "??", "marks"], "cat": "notation", "def": "Marks after a move that judge it: !! brilliant, ! good, ?! dubious, ? a mistake, ?? a blunder.", "game": "The move list carries the Coach's marks for the moves it graded: ?! for an inaccuracy, ? for a mistake, ?? for a blunder, ! for an only move or a mate found, !! for a sound sacrifice. In a two-player game, the Analyze icon after a move says that its side used Analyze before playing it, and the other player is told as their turn comes.", "analysis": "The marks come from the expected score each move gave up against the engine's best, not from taste, so they are consistent from game to game.", "where": "Play: the move list, beside your graded moves (both sides' in a friend game), and the Analyze icon on a move played after using Analyze.", "go": "play", "example": "1. e4 e5 2. Qh5?! Nc6 3. Bc4 Nf6?? 4. Qxf7#", "see": ["coach-grades", "move-grades", "blunder", "coach"]},
  {"id": "material", "term": "Material", "aka": ["pieces", "material count"], "cat": "tactics", "def": "The pieces on the board counted by value. Winning material means taking more than you give.", "game": "Captured pieces collect beside each player's name, with the difference as a number. The Coach states material in words: a knight, the exchange, a bishop for a pawn.", "analysis": "The Coach plays an exchange in progress to its end before it counts, so a recapture still to come is not called a loss.", "engine": "Stockfish's NNUE net does not count material separately; it is learned inside the evaluation.", "where": "The player cards beside the board; the Coach's notes.", "example": "Taking a rook with a knight: up the exchange.", "see": ["piece-values", "material-balance", "exchange", "evaluation"]},
  {"id": "piece-values", "term": "Piece values", "aka": ["point values", "pawn = 1"], "cat": "tactics", "def": "The usual scale: pawn 1, knight 3, bishop 3, rook 5, queen 9. The king cannot be traded and has no value on it.", "game": "The material difference on the player cards counts by this scale, and so does the Coach when it says what a move wins.", "analysis": "The scale is a guide. Activity, safety and structure move the real value; an engine score of +1.00 is roughly a pawn's worth, but not always a pawn on the board.", "engine": "Engine scores are given in centipawns, a hundredth of a pawn, though the evaluation behind them is not a sum of piece values.", "where": "The player cards and the Coach.", "example": "A rook for a bishop and a pawn: 5 against 4.", "see": ["material", "centipawn", "exchange"]},
  {"id": "material-balance", "term": "Material balance", "aka": ["+3", "captured pieces", "material difference"], "cat": "tactics", "def": "The difference in material between the two sides, shown as a plus number for the side ahead.", "game": "On the player cards at each end of the board: the pieces each side has taken in this game, and +3 beside the side that is three points up. A game from a set-up position starts with nothing taken, whatever pieces are missing from a full set.", "analysis": "A material lead the evaluation does not share points to compensation: activity, attack, or a pawn about to fall back.", "where": "The player cards beside the board. Position, Read: the material bar and the piece rows.", "example": "+2 beside Marble: White has won a knight for a pawn.", "see": ["material", "piece-values", "evaluation"]},
  {"id": "attackers-and-defenders", "term": "Attackers and defenders", "aka": ["attacked", "defended", "counting"], "cat": "tactics", "def": "The pieces that attack a square, and the pieces that guard it. If attackers outnumber defenders, or a cheaper piece attacks a dearer one, the piece on the square is in danger.", "game": "The Coach counts them on your turn: a piece attacked and not defended is loose; one attacked more often than defended, where the exchange loses, is outnumbered.", "analysis": "The Tactical X-Ray shows the count for any square: threads from each attacker and defender, beads on the ring for each.", "engine": "Stockfish weighs exchanges with static exchange evaluation, playing out the captures on one square cheapest first.", "where": "Analyze: the Tactical X-Ray. Play: the Coach's watch notes.", "go": "analyze", "example": "A knight on f6 attacked by a bishop and a queen and defended by a pawn and the queen: two against two.", "see": ["hanging-piece", "tactical-xray", "exchange", "pin"]},
  {"id": "hanging-piece", "term": "Hanging piece", "aka": ["loose piece", "en prise", "undefended"], "cat": "tactics", "def": "A piece that is attacked and not defended, or one that can be taken for less than it is worth.", "game": "On your turn the Coach names your loose pieces first (\"Your bishop on c4 is loose: attacked, not defended\"). After a move that leaves one, it says so in the verdict.", "analysis": "In the X-Ray, a hanging piece reads as attacked with no defenders; its expected-score arc shows what losing it costs.", "engine": "A hanging piece usually appears in the engine line as an immediate capture.", "where": "Play: the Coach. Analyze: the X-Ray.", "go": "play", "example": "1. e4 e5 2. Nf3 Qh4?? : the queen stands where the knight on f3 already attacks it, with no defender.", "see": ["attackers-and-defenders", "tactical-xray", "coach", "blunder"]},
  {"id": "fork", "term": "Fork", "aka": ["double attack", "family fork"], "cat": "tactics", "def": "One piece attacking two or more targets at once. The opponent can save only one.", "game": "The Coach names a fork when a move attacks two targets at once, the king among them or two pieces worth more than the attacker, and it reads one out when the opponent plays it.", "analysis": "A fork usually shows as a check or a threat followed by a capture two plies later in the engine line.", "where": "Play: the Coach's notes.", "example": "Nc7+ attacking the king on e8 and the rook on a8.", "see": ["pin", "skewer", "discovered-attack", "double-check"]},
  {"id": "pin", "term": "Pin", "aka": ["pinned", "absolute pin", "relative pin"], "cat": "tactics", "def": "A piece that cannot move off a line without exposing a more valuable piece behind it. Against the king the pin is absolute: the piece may not move at all.", "game": "The Coach names a pin when a move pins a piece to the king, or to a piece worth more than the pinned one. A pawn pinned to a rook is left unsaid.", "analysis": "Pinned pieces are poor defenders: the X-Ray counts them as defenders anyway, so read its count with the pin in mind.", "engine": "The engine's move generator knows absolute pins; relative pins are only seen through search.", "where": "Play: the Coach.", "example": "Bb5 pins the knight on c6 to the king on e8.", "see": ["skewer", "fork", "attackers-and-defenders"]},
  {"id": "skewer", "term": "Skewer", "aka": ["x-ray attack"], "cat": "tactics", "def": "An attack on a valuable piece that, when it moves, exposes a lesser piece behind it on the same line. A pin in reverse.", "game": "The Coach calls a skewer when a long-range piece attacks a valuable piece with a lesser one behind it.", "analysis": "Skewers along ranks and diagonals are common in endgames with rooks and bishops.", "where": "Play: the Coach.", "example": "Rook check on the eighth rank; the king steps aside and the rook takes the queen behind it.", "see": ["pin", "fork", "discovered-attack"]},
  {"id": "discovered-attack", "term": "Discovered attack", "aka": ["discovery", "discovered check"], "cat": "tactics", "def": "A piece moves out of the way and uncovers an attack by the piece behind it. If the uncovered attack is on the king, it is a discovered check.", "game": "The Coach names discovered attacks and discovered checks, and the hint's first nudge says to look for one when that is the engine's idea.", "analysis": "Discoveries are strong because the moving piece is free to make a second threat of its own.", "where": "Play: the Coach and the hint.", "example": "A bishop on b2 behind a knight on e5: Ng4 uncovers the bishop's attack on h8.", "see": ["double-check", "fork", "pin"]},
  {"id": "double-check", "term": "Double check", "aka": ["double-check"], "cat": "tactics", "def": "Check from two pieces at once, always after a discovery. Neither block nor capture can answer both: the king must move.", "game": "The Coach treats a double check as urgent and names it ahead of anything else the move does.", "analysis": "A double check with the king boxed in is often mate.", "engine": "In double check the engine generates king moves only.", "where": "Play: the Coach.", "example": "Réti – Tartakower, Vienna 1910: 9. Qd8+ Kxd8 10. Bg5++, check from the bishop and the rook on d1 at once, and 11. Bd8# follows.", "see": ["check", "discovered-attack", "checkmate"]},
  {"id": "sacrifice", "term": "Sacrifice", "aka": ["sac", "brilliant"], "cat": "tactics", "def": "Giving up material on purpose for something worth more: an attack, a mate, a lasting advantage.", "game": "When you give up at least two points of material, the engine still likes the move, and you were not already winning easily, the Coach calls it Brilliant and marks it !!.", "analysis": "A sacrifice the engine stands behind shows as a material loss in the line with a score that holds or rises.", "engine": "The engine has no notion of sacrifice; it sees a line whose end position is worth more.", "where": "Play: the Coach's Brilliant grade and the !! mark.", "go": "analyze", "example": "Kasparov – Topalov 1999, 24. Rxd4!! cxd4: the Reference in Analyze starts from this position.", "see": ["gambit", "material", "coach-grades", "reference-run"]},
  {"id": "exchange", "term": "Exchange", "aka": ["trade", "the exchange", "up the exchange"], "cat": "tactics", "def": "A trade of pieces. \"The exchange\" in particular is a rook for a bishop or knight: winning it means getting the rook.", "game": "The Coach says \"the exchange\" for rook against minor piece, and plays an exchange in progress to its end before it judges the material.", "analysis": "Who should trade: the side ahead in material trades pieces, the side behind keeps them on. One of the Coach's maxims says so.", "engine": "Static exchange evaluation, the engine's counting of captures on one square, decides which exchanges it even searches first.", "where": "Play: the Coach.", "example": "Rxe5 dxe5: a rook for a knight, losing the exchange.", "see": ["material", "piece-values", "attackers-and-defenders"]},
  {"id": "tempo", "term": "Tempo", "aka": ["tempi", "a move", "with gain of tempo"], "cat": "tactics", "def": "A single move as a unit of time. Gaining a tempo means making a useful move that also forces the opponent to answer.", "game": "The Coach's opening habits are about tempi: moving the same piece twice, or bringing the queen out to be chased, gives them away.", "analysis": "In races (pawns to queen, attacks on opposite wings), count the tempi each side needs.", "where": "Play: the Coach's opening notes.", "example": "Developing a knight with an attack on the queen gains a tempo.", "see": ["development", "initiative", "zugzwang"]},
  {"id": "initiative", "term": "Initiative", "aka": ["pressure"], "cat": "tactics", "def": "The power to make threats that the opponent must answer, so that you choose where the game goes.", "game": "The Coach's watch notes are the other side of it: when the opponent has the initiative, you read its threat first.", "analysis": "An initiative can be worth material: an engine score that holds after a pawn sacrifice often means the pressure pays for it.", "where": "Play: the Coach's threat notes.", "see": ["tempo", "sacrifice", "gambit"]},
  {"id": "zugzwang", "term": "Zugzwang", "aka": ["compulsion to move"], "cat": "tactics", "def": "A position where the side to move would be better off passing, because every move makes things worse.", "game": "Common in king and pawn endings: taking the opposition puts the other king in zugzwang.", "analysis": "The Coach's threat search works by passing the move to the opponent. In zugzwang, passing is exactly what the side to move would like to do, so a threat read that way does not apply.", "engine": "Null-move pruning also passes a move to prove a position good. Stockfish does not try it when the side to move has only its king and pawns, where zugzwang is common.", "where": "Endgames on any board; Position, Studies: the king and pawn studies.", "go": "position", "example": "The opposition in a king and pawn ending: the kings face each other with one square between them, and whoever must move gives way.", "see": ["endgame", "tempo"]},
  {"id": "development", "term": "Development", "aka": ["develop", "developing"], "cat": "tactics", "def": "Bringing the pieces from their starting squares into play, knights and bishops first, in the opening.", "game": "The Coach tracks it: it notes when all four minor pieces are out, reminds you when two are still home, and points out a piece moved twice while others wait.", "analysis": "An early lead in development matters most when the centre opens.", "where": "Play: the Coach, from games that start at the initial position.", "example": "1. e4 e5 2. Nf3 Nc6 3. Bc4 Bc5: both sides developing toward the centre.", "see": ["opening", "tempo", "castling", "centre"]},
  {"id": "centre", "term": "Centre", "aka": ["center", "central squares", "e4 d4 e5 d5"], "cat": "tactics", "def": "The four squares e4, d4, e5 and d5, and the area around them. Pieces there reach the most squares; pawns there claim space.", "game": "The Coach's first tip in a new game is to fight for the centre, and it notes moves that claim or contest it.", "analysis": "A pawn centre can be strong or a target; the evaluation weighs which.", "where": "Play: the Coach's tips and reasons.", "example": "1. e4 claims the centre and opens lines for the queen and the bishop.", "see": ["development", "opening", "king-safety"]},
  {"id": "king-safety", "term": "King safety", "aka": ["king shelter", "pawn shield"], "cat": "tactics", "def": "How well the king is sheltered: the pawns in front of it, the pieces near it, and the open lines toward it.", "game": "The Coach tells you to castle before the centre opens, notes a king walk while castling is still possible, and flags moves that loosen the pawns in front of your king.", "analysis": "Attacks on the king often justify material: a score that favours the attacker despite fewer pieces is a sign.", "engine": "King safety is one of the largest terms in any chess evaluation; NNUE learns it from the position.", "where": "Play: the Coach. Position, Read: Structure, the Kings chip (each king and the pawns in front of it).", "example": "After castling kingside, g4 loosens the shelter.", "see": ["castling", "check", "development"]},
  {"id": "opening", "term": "Opening", "aka": ["opening phase", "opening theory"], "cat": "tactics", "def": "The first phase of the game: the pieces come out, the kings get safe, the centre is contested. Known openings have names.", "game": "The turn card names the opening you are in (with its ECO code), from the lichess opening list. The Coach grades moves from that list as Book and names the opening when the game enters a new one.", "analysis": "The heartbeat shows book moves as plain slots; engine moves are shaded by how far the evaluation moved.", "engine": "Stockfish has no opening book here; it searches from the first move.", "where": "Play: the opening line on the turn card, the Coach's Book grade. Crucible: each game's opening. Position, Read: the phase meter.", "go": "play", "example": "1. e4 e5 2. Nf3 Nc6 3. Bc4 : C50, Italian Game.", "see": ["book-move", "eco", "development", "middlegame"]},
  {"id": "middlegame", "term": "Middlegame", "aka": ["middle game"], "cat": "tactics", "def": "The phase after the opening, with most pieces still on: plans, attacks and manoeuvres.", "game": "The Coach's tips change with the phase: here, find your least active piece, make a plan, or put a rook on an open file when there is one.", "analysis": "The page calls it the middlegame from move 11, or sooner once the side to move has at most one minor piece at home and has castled or lost the right to, until enough material is off for an endgame.", "where": "Play: the Coach's tips and its maxims for the phase. Position, Read: the phase meter.", "see": ["opening", "endgame", "initiative"]},
  {"id": "endgame", "term": "Endgame", "aka": ["ending", "end game"], "cat": "tactics", "def": "The phase with little material left, where the king becomes a fighting piece and passed pawns decide.", "game": "The Coach's tips here fit the board: the mate against a bare king, the king's march to the centre, a rook behind a passed pawn. It watches for stalemate and counts the fifty moves.", "analysis": "The page treats the game as an endgame when the pieces other than pawns and kings add up to 26 points or less, or 32 or less with no queens.", "engine": "The browser build has no endgame tablebases, so even simple endings are searched, not looked up.", "where": "Play: the Coach. Position, Read: the phase meter; Studies, Endgames: king and pawn, the square of the pawn, Lucena and Philidor.", "go": "position", "example": "Lucena position (Position, Studies): White builds a bridge with the rook to shield the king and queen the pawn.", "see": ["zugzwang", "stalemate", "fifty-move-rule", "tablebases"]},
  {"id": "gambit", "term": "Gambit", "aka": ["gambits"], "cat": "tactics", "def": "An opening that gives a pawn, sometimes more, for development, the centre or an attack.", "game": "A gambit from the opening list is graded Book like any other known line; the Coach adds a word when the engine does not trust a known line.", "analysis": "Engines judge gambits coldly: many score a pawn down. Over the board the time they gain can matter more.", "example": "1. e4 e5 2. f4 : the King's Gambit.", "see": ["sacrifice", "opening", "book-move", "initiative"]},
  {"id": "evaluation", "term": "Evaluation", "aka": ["eval", "score", "engine score"], "cat": "eval", "def": "The engine's judgement of a position as one number: how much better one side stands, in pawns, or a forced mate.", "game": "Turn on Evaluation (in the Coach card's Engine lines) and a bar beside the board and the engine's best line follow the game. It is off by default, so the game stays yours.", "analysis": "Read it as a trend, not a verdict: +0.30 is a normal first-move edge, +1.00 about a pawn, +3.00 usually winning. A score that changes a lot with depth means the position is not settled.", "engine": "Stockfish evaluates the leaves of its search with its NNUE network and backs the scores up the tree; the number shown is the root's score at the deepest finished depth.", "where": "Play: Coach card, Engine lines, Evaluation (bar and best line). Analyze: the line table. Crucible: each game's evals on the heartbeat.", "go": "play", "example": "+0.30 after 1. e4: White's usual opening edge.", "see": ["centipawn", "white-view", "eval-bar", "expected-score", "mate-score"]},
  {"id": "centipawn", "term": "Centipawn", "aka": ["cp", "centipawns"], "cat": "eval", "def": "A hundredth of a pawn, the unit engines use for scores. 100 centipawns is about one pawn's worth of advantage.", "game": "The page shows scores in pawns, not centipawns: cp 140 from the engine reads +1.40.", "analysis": "The Calculate moves and Analyze grades are measured in centipawns lost against the best line: up to 10 is Best, up to 60 Good, up to 150 Inaccurate.", "engine": "UCI reports score cp 140 from the side to move. Stockfish calibrates its scale so that +1.00 means about a 50 % chance of winning at its own level of play.", "where": "Hidden inside every score; visible as a unit only in the engine's UCI output.", "example": "score cp −35 with Black to move is +0.35 from White's view.", "see": ["pawn-units", "evaluation", "move-grades", "white-view"]},
  {"id": "pawn-units", "term": "Pawn units", "aka": ["pawns", "+1.40", "score format"], "cat": "eval", "def": "Scores written in pawns with a sign: +1.40 means White is better by about a pawn and a half, −0.35 means Black is slightly better.", "game": "Play's evaluation bar rounds to one decimal (+0.3); the line table in Analyze and the Coach's notes show two (+0.34).", "analysis": "Thresholds in the app are in pawns too: Crucible adjudicates a win at |eval| of 10.00 for 4 plies, flags an anomaly when a balanced game (within 1.50) turns decisive (5.00 or more), and the heartbeat draws rules at ±5.00.", "engine": "The engine's centipawns divided by 100, turned to White's view.", "where": "Every score in the app, with a true minus sign.", "example": "+1.40 for 25. Re7+ in the Reference.", "see": ["centipawn", "white-view", "mate-score", "adjudication"]},
  {"id": "mate-score", "term": "Mate score", "aka": ["#3", "M3", "mate in", "forced mate"], "cat": "eval", "def": "A score that counts moves to a forced mate instead of pawns. #3 means the side named mates in three moves; #−3 means Black does.", "game": "Play's bar shows +M3 or −M3 and fills to the end. The Coach says when you have a mate in one to three, and when you let one go.", "analysis": "Analyze shows #n from White's view. A shorter mate is ranked above a longer one, and any mate above any pawn score.", "engine": "UCI score mate 3 counts the mover's own moves; mate −2 means the mover is mated in two. Recorded files carry a large cp beside a mate, and the mate wins.", "where": "Play: the evaluation bar and the Coach. Analyze: the line table, the Synaptic PV's Mate note.", "go": "analyze", "example": "#−1: Black mates next move.", "see": ["checkmate", "evaluation", "expected-score", "coach-grades"]},
  {"id": "white-view", "term": "White's view", "aka": ["White view", "from White's side", "POV"], "cat": "eval", "def": "The convention that every score in MONOLITH is given from White's side: plus is good for White, minus good for Black, whoever is to move.", "game": "Playing Black, a falling score is good news for you. The Coach's notes show the score after a move the same way.", "analysis": "Engines report from the side to move; the page flips Black-to-move scores so a column of numbers reads consistently down the move list and the heartbeat.", "engine": "UCI scores are from the side to move. The page multiplies by −1 when Black is to move, and turns WDL around the same way.", "where": "Every score: the line table (White's view, graded by loss against line 1), the WDL ribbon, the evaluation bar, the heartbeat.", "example": "Black to move, engine says cp 50: the page shows −0.50.", "see": ["side-to-move", "evaluation", "wdl", "expected-score"]},
  {"id": "expected-score", "term": "Expected score", "aka": ["win chance", "expected points", "E"], "cat": "eval", "def": "A score turned into the points a side can expect from the position, between 0 and 1: 0.5 is level, 0.8 means about four points in five. Mate counts as 1 or 0.", "game": "The Coach grades moves by how much expected score they give up, so a slip in a level position weighs more than the same slip in a won one.", "analysis": "Sharpness, the root field, the fork walk's gaps and the X-Ray's arc are all differences in expected score. Shown as a percentage: line 1 to line 2, 45.2 %.", "engine": "The page uses the logistic 1 / (1 + e^(−cp / 271.6)), fitted to Dennis's recorded field and the same curve lichess uses for its win chances. It is not the engine's WDL, which comes from Stockfish's own model.", "where": "Analyze: Sharpness, the field legend, the X-Ray. Play: the Coach's grades and its game review.", "go": "analyze", "example": "+1.00 is an expected score of about 59 %; +3.00 about 75 %.", "see": ["sharpness", "coach-grades", "accuracy", "wdl"]},
  {"id": "wdl", "term": "WDL", "aka": ["win draw loss", "UCI_ShowWDL", "W / D / L"], "cat": "eval", "def": "Win, draw and loss chances for a line, per mille, from the engine's own model. They add up to 1000.", "analysis": "Analyze shows WDL for each line as a small bar with percentages, and the ribbon beside the board for the position, both from White's view. A large draw share with a plus score means a small, safe edge; a small draw share means a sharp game.", "engine": "Stockfish reports wdl 884 116 0 when UCI_ShowWDL is on, from the side to move, at its own strength. The Stockfish 10 fallback has no WDL; the page says WDL not reported.", "where": "Analyze: UCI options, UCI_ShowWDL; the line table; the WDL ribbon with Sharpness.", "go": "analyze", "example": "Reference line 1: 88 / 12 / 0 for White.", "see": ["expected-score", "sharpness", "white-view", "uci-options"]},
  {"id": "eval-bar", "term": "Evaluation bar", "aka": ["eval bar", "bar"], "cat": "eval", "def": "A vertical bar beside the board, marble from below and obsidian from above, split where the evaluation puts the position.", "game": "Turn it on with Evaluation in Engine lines, or Evaluation bar in Settings (Game). It turns with the board when you flip it; when the game is over it fills for the winner and the score reads 1–0, 0–1 or ½–½.", "analysis": "It squashes large scores: the fill follows a gentle logistic (350 centipawns), so +3.00 fills 70 % and the last stretch is reserved for mates. Read the number in the best line for detail.", "engine": "It reads the play engine's search of the shown position to depth 16, run between your moves, never while the computer is thinking.", "where": "Play: beside the board, when Evaluation is on. Settings, Game: Evaluation bar. Palette: :eval.", "go": "play", "example": "Half at 0.0, 60 % marble at +1.40, 70 % at +3.00, all of it at +M3.", "see": ["evaluation", "best-line", "white-view"]},
  {"id": "best-line", "term": "Best line", "aka": ["engine line", "main line"], "cat": "eval", "def": "The engine's best continuation from the position, with its score.", "game": "Under Evaluation, the best line shows the score and the first eight plies in SAN. It is a look ahead, not advice for the whole game.", "analysis": "The deeper moves of a line are less reliable than the first: the engine spent most of its effort near the root.", "engine": "The principal variation from the play engine's search (depth 16).", "where": "Play: Coach card, Engine lines, under the Evaluation switch.", "go": "play", "example": "+0.3 1.e4 e5 2.Nf3 Nc6 3.Bb5 a6 4.Ba4 Nf6", "see": ["principal-variation", "eval-bar", "calculate-moves"]},
  {"id": "move-grades", "term": "Move grades", "aka": ["Best", "Good", "Inaccurate", "Mistake", "line grades", "arrow colours"], "cat": "eval", "def": "The grades on candidate lines in Calculate moves and on Analyze's line table: each line against line 1, by centipawns lost. Best up to 0.10, Good up to 0.60, Inaccurate up to 1.50, Mistake beyond.", "game": "Calculate moves draws its candidates as arrows in the grade's colour (green, olive, orange, red in the cathedral). The Coach grades your own moves differently, by expected score (see Coach grades).", "analysis": "In MONOLITH the grades take the semantic colours: cyan for the best line, ink for good, amber for an inaccuracy, crimson for a mistake.", "engine": "Mate lines rank above every pawn score, a shorter mate above a longer one; a line being mated ranks below all.", "where": "Play: Calculate moves. Analyze: the MultiPV table.", "go": "analyze", "example": "Line 1 +0.40, line 2 +0.25 (Good, 0.15 lost), line 3 −1.30 (Mistake, 1.70 lost).", "see": ["coach-grades", "calculate-moves", "multipv", "centipawn"]},
  {"id": "blunder", "term": "Blunder", "aka": ["??", "blunders"], "cat": "eval", "def": "A move that throws away a large part of the result. The Coach calls a move a Blunder when it gives up 20 % or more of the expected score.", "game": "The verdict says what the move allows and what was better; a house maxim may follow, and the move list marks it ??. Allowing a forced mate is graded by lichess's rule: a blunder, unless the position was already lost (a mistake from −7.00 for the mover, an inaccuracy from −10.00).", "analysis": "The end-of-game review counts your blunders and names the turning point, the move that cost the most.", "where": "Play: the Coach and the move list.", "go": "play", "example": "3… Nf6?? allows 4. Qxf7#.", "see": ["coach-grades", "annotation-symbols", "swing", "accuracy"]},
  {"id": "swing", "term": "Swing", "aka": ["eval swing", "delta", "max swing"], "cat": "eval", "def": "How far the evaluation moves from one move to the next.", "game": "The Coach's review finds the move with the biggest loss and calls it the turning point.", "analysis": "The Crucible heartbeat shades each engine move by its swing: quiet under 0.30, notable from 0.30, amber from 1.00, crimson from 3.00. Book moves sit in plain slots.", "engine": "A big swing between two of an engine's own searches usually means the other engine's move, or the earlier search, missed something.", "where": "Crucible: the heartbeat and its hover readout. Play: the Coach's turning point.", "go": "crucible", "example": "Game 78: +0.93 to +7.47 after 48. Bxc3, a severe swing.", "see": ["heartbeat", "anomaly", "blunder"]},
  {"id": "stockfish", "term": "Stockfish", "aka": ["SF", "SF19", "Stockfish 19"], "cat": "engine", "def": "The free, open-source chess engine (GPL-3.0) that plays, coaches and analyses in MONOLITH. Here it is Stockfish 19.0.1 lite, compiled to WebAssembly and run in the browser.", "game": "It is the opponent at every level, the Coach's reader, and the source of hints. A game uses two copies: one plays, one coaches.", "analysis": "Analyze runs two more (the main search and the field), and the Crucible two per game slot, so A and B never share a hash table.", "engine": "Each copy is a Web Worker speaking UCI. The lite build has a smaller NNUE net than desktop Stockfish and one thread.", "where": "Analyze: the Engine card names the build. Settings, Help and about. The WORKERS cell in the footer counts the copies.", "go": "analyze", "example": "Engine card: Stockfish 19, WASM build, 1 thread, Hash 64 MB, MultiPV 5.", "see": ["wasm-build", "uci", "nnue", "stockfish-10-fallback"]},
  {"id": "uci", "term": "UCI", "aka": ["Universal Chess Interface"], "cat": "engine", "def": "The Universal Chess Interface: the text protocol between a chess program and an engine. The page sends commands; the engine answers with info lines and a best move.", "game": "Every computer move starts as position ... and go ..., and ends with bestmove.", "analysis": "Every readout in Analyze is badged with the UCI field it came from: [SF: UCI info], [SF: MultiPV], [SF: WDL].", "engine": "The page sends uci, setoption (only the options that changed), ucinewgame, position, go and stop; it reads id, option, info and bestmove.", "where": "Analyze: the Engine card ([SF: UCI info]) and the UCI options.", "go": "analyze", "example": "position startpos moves e2e4 e7e5, then go depth 12 movetime 1500.", "see": ["uci-options", "info-stream", "bestmove", "long-algebraic"]},
  {"id": "uci-options", "term": "UCI options", "aka": ["setoption", "engine options"], "cat": "engine", "def": "Settings an engine exposes through UCI, such as Hash, Threads and MultiPV.", "analysis": "Analyze, UCI options, holds Threads (1, fixed), Hash (16 to 256 MB), MultiPV (1 to 5), UCI_ShowWDL, the search limit (10 to 120 s), the field depth and the fork walk depth. The last three are the page's settings, not the engine's.", "engine": "The page sends an option only when it changes. Options the loaded engine lacks are disabled with the reason, rather than accepted and ignored.", "where": "Analyze: UCI options (folded). Crucible: the UCI parameter matrix compares A and B.", "go": "analyze", "example": "setoption name MultiPV value 5", "see": ["hash", "multipv", "threads", "parameter-matrix"]},
  {"id": "depth", "term": "Depth", "aka": ["search depth", "d20"], "cat": "engine", "def": "How many plies deep the engine has searched its main line in full. Each finished depth is one iteration.", "game": "The levels differ partly by depth: Novice searches 3 plies, Strong 8, Maximum up to 20. The Coach reads each position to depth 12.", "analysis": "Analyze shows depth and selective depth as 26/68. Results at low depth can flip; a line that holds from depth 15 to 25 is trustworthy.", "engine": "Stockfish deepens one ply at a time (iterative deepening); along forcing lines it searches deeper (see Seldepth).", "where": "Analyze: Depth in the Engine card, d26 in the badges, the search profile. Play: Calculate moves shows its depth.", "go": "analyze", "example": "Depth 26/68: 26 plies in full, 68 at the deepest point.", "see": ["seldepth", "iterative-deepening", "search-profile", "skill-levels"]},
  {"id": "seldepth", "term": "Seldepth", "aka": ["selective depth"], "cat": "engine", "def": "The deepest ply any line reached during the search, through extensions and quiescence, as opposed to the nominal depth searched in full.", "analysis": "Shown after the slash in Analyze's depth: 26/68. A big gap between the two is normal in tactical positions.", "engine": "UCI info seldepth. Checks, captures and recaptures are searched past the nominal depth until the position is quiet.", "where": "Analyze: the Depth cell (depth/seldepth).", "go": "analyze", "example": "26/68 in the recorded Reference run.", "see": ["depth", "nodes", "alpha-beta"]},
  {"id": "nodes", "term": "Nodes", "aka": ["positions searched", "node count"], "cat": "engine", "def": "The number of positions the engine has visited in its search so far.", "analysis": "Analyze shows nodes in k, M and G: 29.76 M. More nodes is more work, not automatically a better answer.", "engine": "UCI info nodes. A fixed node count is a repeatable, hardware-independent search limit, which is why the Crucible's configurations use it.", "where": "Analyze: Nodes. Crucible: nodes per move for A and B.", "go": "analyze", "example": "29.76 M nodes in 120 s for the Reference.", "see": ["nps", "nodes-per-move", "depth"]},
  {"id": "nps", "term": "NPS", "aka": ["nodes per second", "speed"], "cat": "engine", "def": "Nodes per second: how fast the engine searches on this device.", "analysis": "One browser thread is far slower than a desktop engine: a few hundred thousand nodes per second is typical. It varies with the device and what else is running.", "engine": "UCI info nps. It falls while other engines share the processor, for example while the field is being computed.", "where": "Analyze: NPS. The footer's NPS cell, with a sparkline of recent values.", "go": "analyze", "example": "248.0 k in the Reference run.", "see": ["nodes", "threads", "telemetry", "wasm-build"]},
  {"id": "hash", "term": "Hash", "aka": ["transposition table", "TT", "Hash MB"], "cat": "engine", "def": "The engine's transposition table: memory where it stores positions it has already searched, so it does not search them twice.", "analysis": "Analyze lets you choose 16 to 256 MB (64 by default). More hash helps long searches; for short ones it hardly matters.", "engine": "Each engine has its own: the Coach's is 32 MB, each Crucible engine 16 MB. On the Stockfish 10 fallback the page caps it at 16 MB and says engine maximum.", "where": "Analyze: UCI options, Hash; the Engine card. Crucible: the parameter matrix.", "go": "analyze", "example": "The Reference run: Hash 256 MB, 61.8 % full after 120 s.", "see": ["hashfull", "uci-options", "search-profile"]},
  {"id": "hashfull", "term": "Hashfull", "aka": ["hash full", "hash usage", "HASH"], "cat": "engine", "def": "How full the engine's transposition table is, reported in per mille and shown here as a percentage.", "analysis": "It climbs over a long search. Near 100 % the engine starts overwriting useful entries; for an infinite search on a deep position, a larger Hash helps.", "engine": "UCI info hashfull 618 is 61.8 %. Stockfish estimates it from a sample of the table.", "where": "Analyze: Hashfull. The footer's HASH cell, with a meter. The search profile plots it over time.", "go": "analyze", "example": "61.8 % after the Reference's 120 s with 256 MB.", "see": ["hash", "search-profile", "telemetry"]},
  {"id": "threads", "term": "Threads", "aka": ["cores", "SMP"], "cat": "engine", "def": "How many processor threads the engine searches with.", "analysis": "Always 1 here: the browser build is single-threaded. Desktop Stockfish on many threads would search many times faster.", "engine": "The page runs several single-threaded engines side by side instead (play, Coach, analysis, Crucible pairs), each its own Web Worker.", "where": "Analyze: UCI options, Threads, fixed at 1. The footer's WORKERS cell.", "go": "analyze", "see": ["wasm-build", "nps", "parallel-games"]},
  {"id": "multipv", "term": "MultiPV", "aka": ["multi PV", "lines"], "cat": "engine", "def": "The number of best lines the engine reports at once, each with its own score.", "game": "Calculate moves shows 1 to 5 candidate lines (3 by default); the lower levels pick among several lines so that they can choose worse moves.", "analysis": "Analyze reports up to 5 lines; Sharpness compares line 1 with lines 2 and 3. The field runs MultiPV over every legal move; the fork walk runs MultiPV 2.", "engine": "More lines cost search time: each line after the first is searched to the same depth.", "where": "Analyze: the MultiPV table and UCI options. Play: Lines beside Calculate moves.", "go": "analyze", "example": "MultiPV 3 at depth 12 within 1.5 s for each Coach reading.", "see": ["principal-variation", "sharpness", "root-multipv-field", "calculate-moves"]},
  {"id": "principal-variation", "term": "Principal variation", "aka": ["PV", "main line", "line"], "cat": "engine", "def": "The line of best play the engine expects from the position: its move, the best reply, and so on.", "analysis": "Each MultiPV line is a PV. The Synaptic PV lays the lines out as chips you can scrub, and the vectors show each first move.", "engine": "UCI info ... pv e2e4 e7e5 g1f3. The PV is the path the search kept; its later moves were searched less deeply than the first.", "where": "Analyze: the line table, the Synaptic PV, the vectors. Play: the best line.", "go": "analyze", "example": "Reference line 1: 25. Re7+ Kb6 26. Qxd4+ Kxa5 27. b4+.", "see": ["multipv", "synaptic-pv", "best-line", "vectors"]},
  {"id": "search-limit", "term": "Search limit", "aka": ["time limit", "movetime", "Time"], "cat": "engine", "def": "When a search stops: after a depth, a number of nodes, or a time.", "game": "Each level has its own limit (Novice 200 ms to depth 3, Maximum 2.5 s to depth 20); the Coach uses depth 12 within 1.5 s.", "analysis": "Analyze searches each position for 10, 20, 60 or 120 seconds (20 by default), then stops and says so. Go infinite runs past it.", "engine": "UCI go depth, go nodes, go movetime; the page stops a search with stop when its position changes.", "where": "Analyze: UCI options, Search limit; the Time cell; the note beside Go infinite.", "go": "analyze", "example": "stopped at 20.0 s (limit)", "see": ["go-infinite", "depth", "nodes-per-move"]},
  {"id": "go-infinite", "term": "Go infinite", "aka": ["infinite analysis", ":go", ":stop"], "cat": "engine", "def": "A search with no limit: it runs until it is stopped.", "analysis": "Press Go infinite in Analyze to keep searching past the limit, Stop to end it. On the Reference it replaces the recorded run with a live one.", "engine": "UCI go infinite; the engine reports info lines until stop, then gives its best move.", "where": "Analyze: the Engine card. Palette: :go and :stop.", "go": "analyze", "example": "searching · 84.2 s", "see": ["search-limit", "iterative-deepening", "reference-run"]},
  {"id": "iterative-deepening", "term": "Iterative deepening", "aka": ["deepening"], "cat": "engine", "def": "Searching to depth 1, then 2, then 3, and so on, each iteration reusing what the last one learned.", "analysis": "This is why lines appear at once and then improve: each finished depth replaces the last. The search profile draws the depth climbing over time.", "engine": "Each iteration seeds the next with its best move and the hash table, so the deeper searches cut far more of the tree.", "where": "Analyze: the search profile and the line table as it updates.", "go": "analyze", "see": ["depth", "search-profile", "alpha-beta", "hash"]},
  {"id": "alpha-beta", "term": "Alpha-beta", "aka": ["alpha-beta pruning", "minimax", "bounds"], "cat": "engine", "def": "The search method behind chess engines: minimax with pruning, which skips moves that cannot change the result.", "analysis": "Some info lines carry only a bound (lowerbound or upperbound) instead of an exact score; the page uses them for the counters but not for the line table.", "engine": "With good move ordering alpha-beta searches roughly the square root of the full tree; Stockfish adds aspiration windows, null moves and reductions on top.", "where": "Inside the engine; visible as the bound lines the page keeps out of the table.", "see": ["iterative-deepening", "principal-variation", "depth"]},
  {"id": "nnue", "term": "NNUE", "aka": ["neural network", "efficiently updatable neural network"], "cat": "engine", "def": "Efficiently Updatable Neural Network: the evaluation Stockfish has used since version 12, a network fast enough to run at every node of the search.", "analysis": "NNUE scores weigh things a piece count cannot see, such as king safety and activity, which is why +1.00 is not always a pawn on the board.", "engine": "The lite build carries a smaller network than desktop Stockfish, to fit a web download. The Stockfish 10 fallback predates NNUE and uses a hand-written evaluation.", "where": "Inside the engine.", "see": ["stockfish", "evaluation", "wasm-build"]},
  {"id": "wasm-build", "term": "WASM build", "aka": ["WebAssembly", "lite single", "Web Worker"], "cat": "engine", "def": "Stockfish 19.0.1 lite, single-threaded, compiled to WebAssembly and run in a Web Worker inside the page.", "game": "It loads once, then plays without a server. When a Worker cannot start from its own engine folder, the page fetches the same build from unpkg instead.", "analysis": "A browser engine is slower than a desktop one and has one thread, so depths here are lower than on a desktop for the same time.", "engine": "The page tries its own engine/ folder first, then unpkg (jsDelivr refuses the package, which is over its size limit), then the Stockfish 10 asm.js file from cdnjs.", "where": "Analyze: the Engine card (WASM build, or WASM build · unpkg). The footer's WORKERS cell.", "go": "analyze", "see": ["stockfish", "stockfish-10-fallback", "threads"]},
  {"id": "stockfish-10-fallback", "term": "Stockfish 10 fallback", "aka": ["SF10", "asm.js"], "cat": "engine", "def": "The last-resort engine: Stockfish 10 as one asm.js file from cdnjs, used only when the WebAssembly build cannot load.", "game": "It plays and coaches, but it has no UCI_Elo, so Expert and Master are approximated by the page's own move chooser; the level text says so.", "analysis": "No WDL (the page says WDL not reported), and the hash is capped at 16 MB.", "engine": "It predates NNUE and searches more slowly than the WebAssembly build.", "where": "Analyze: the Engine card names it when it is the one running; labels and options follow it.", "see": ["wasm-build", "uci-elo", "wdl", "skill-levels"]},
  {"id": "uci-elo", "term": "UCI_Elo", "aka": ["UCI_LimitStrength", "Elo limiter"], "cat": "engine", "def": "A UCI option that limits the engine to play at about a given rating.", "game": "Levels 6 and 7, Expert and Master, are Stockfish limited to about 2000 and 2500.", "analysis": "The limiter's ratings are on Stockfish's own scale, calibrated by its developers against engine rating lists, not against an online pool of human players.", "engine": "Stockfish accepts 1320 to 3190. The Crucible's UCI_Elo configurations use it at 150 ms a move.", "where": "Play: Difficulty and Computer strength. Crucible: Live run, Stockfish 19 · UCI_Elo.", "go": "play", "example": "Expert: UCI_Elo 2000, depth 12 within 0.9 s.", "see": ["skill-levels", "elo", "stockfish-10-fallback"]},
  {"id": "skill-levels", "term": "Levels", "aka": ["Difficulty", "Computer strength", "Novice", "Beginner", "Casual", "Club", "Strong", "Expert", "Master", "Maximum"], "cat": "engine", "def": "The computer's eight strengths: Novice, Beginner, Casual, Club, Strong, Expert, Master and Maximum.", "game": "Levels 1 to 5 let Stockfish search several lines to a shallow depth (3 to 8 plies) and pick among them, worse moves less often the higher the level, with a chance of a random move (30 % at Novice, 1 % at Strong). Levels 6 and 7 are Stockfish limited by UCI_Elo; Maximum is unrestricted. Change it mid-game under Computer strength.", "analysis": "The levels are calibrated against Stockfish's own UCI_Elo anchors by a tool beside the page (tools/calibrate.js).", "engine": "Novice: 8 lines, depth 3, 200 ms. Strong: 4 lines, depth 8, 600 ms. Expert: UCI_Elo 2000. Master: UCI_Elo 2500. Maximum: depth 20 within 2.5 s.", "where": "Play: Difficulty in setup, Computer strength in the game. Crucible: MONOLITH level as an engine configuration.", "go": "play", "example": "Club, level 4 of 8: a solid club player that takes free material and makes the odd inaccuracy.", "see": ["uci-elo", "multipv", "depth", "stockfish"]},
  {"id": "tablebases", "term": "Tablebases", "aka": ["Syzygy", "endgame tablebases", "EGTB"], "cat": "engine", "def": "Precomputed databases of every position with few pieces, giving the exact result and the best move.", "analysis": "Not available here: the browser build has no Syzygy support, so even simple endings are searched rather than looked up.", "engine": "Desktop Stockfish probes Syzygy files when it reaches positions with few enough pieces and counts the probes as tbhits.", "where": "Nowhere in the app; the TB hits readout says not reported.", "see": ["tb-hits", "endgame", "wasm-build"]},
  {"id": "tb-hits", "term": "TB hits", "aka": ["tbhits", "TB HITS"], "cat": "engine", "def": "How many times the engine looked a position up in its endgame tablebases during the search.", "analysis": "Here it reads not reported: this build has no Syzygy, so the engine does not send the field. The recorded run reports 0.", "engine": "UCI info tbhits.", "where": "Analyze: TB hits. The footer's TB HITS cell.", "go": "analyze", "see": ["tablebases", "info-stream"]},
  {"id": "bestmove", "term": "bestmove", "aka": ["best move"], "cat": "engine", "def": "The engine's final answer to a search, in long algebraic: bestmove g1f3.", "game": "At Expert, Master and Maximum the computer plays it. Lower levels choose among the searched lines instead.", "engine": "Sent once per go, after the last info line. bestmove (none) means there is no legal move; in the Crucible that ends a game as no move from engine.", "where": "Inside the UCI traffic; the computer's move in Play.", "see": ["uci", "long-algebraic", "skill-levels"]},
  {"id": "info-stream", "term": "Info stream", "aka": ["info lines", "UCI info"], "cat": "engine", "def": "The running report an engine sends while it searches: depth, score, nodes, speed, hash use and the line, many times a second.", "analysis": "The search profile is drawn from it, and the footer reads it live. Badges such as [SF: info stream] mark readouts that come straight from it.", "engine": "Each line starts with info. The page keeps the deepest exact line for each MultiPV slot and drops a stale copy of a move that moved to another slot.", "where": "Analyze: the stats, the search profile. The footer.", "go": "analyze", "example": "info depth 26 seldepth 68 multipv 1 score cp 140 wdl 884 116 0 nodes 29764908 nps 248038 hashfull 618", "see": ["uci", "search-profile", "source-badges", "telemetry"]},
  {"id": "perft", "term": "Perft", "aka": ["performance test", "move path enumeration"], "cat": "engine", "def": "A test of a move generator: count every position reachable in n plies and compare with known totals.", "analysis": "The page's own rules engine, the one that decides which moves you may play, is checked this way.", "engine": "From the starting position there are 20, 400, 8,902 and 197,281 positions at depths 1 to 4; the page matches these and the standard test positions (Kiwipete among them).", "where": "Not in the interface; part of how the rules are verified for each release.", "see": ["legal-move", "castling", "en-passant", "promotion"]},
  {"id": "monolith", "term": "MONOLITH", "aka": ["Monolith", "the instrument", "Monolith world"], "cat": "analysis", "def": "The second world, whose name the whole app carries, after Dennis's design plates: a dark, precise room that holds the chess instrument, where Analyze and the Crucible live.", "game": "You can play in it too: Settings, World, MONOLITH keeps it for every tab. On Auto, the page moves you there for Analyze and the Crucible and back to the cathedral for Play.", "analysis": "Colour carries meaning there and nothing else: cyan for the optimal, amber for volatility, crimson for an anomaly or a refutation. Structure is ink, steel and slate.", "where": "Analyze and Crucible on Auto; Settings, World and graphics: World. Settings, Help and about: MONOLITH system shows its solved colours and measures their contrast in your browser.", "go": "analyze", "see": ["worlds", "root-multipv-field", "crucible", "telemetry"]},
  {"id": "root-multipv-field", "term": "Root move-value field", "aka": ["Field", "field", "move-value field", "Root MultiPV Field", "F"], "cat": "analysis", "def": "A glow beneath the board's squares: every legal move scored at once, each square lit by the best move that lands on it.", "game": "It answers where the good moves go: bright squares take good moves, dark ones take moves that lose.", "analysis": "Brightness is full for the best move and dark at a loss of 50 % expected score or more. The Sharpness note counts the moves within 5 % of the best; one bright square in a dark board means one move holds.", "engine": "A second engine searches with MultiPV set to every legal move, to the field depth (10 by default, 8 to 16 in UCI options). The Reference was recorded at depth 16.", "where": "Analyze: the Field toggle on the stage (or F), the legend [SF: Root MultiPV Field]. Palette: :field.", "go": "analyze", "example": "Reference: 45 legal moves, one within 5 % of the best, one square lit: e7.", "see": ["multipv", "tactical-xray", "sharpness", "expected-score"]},
  {"id": "vectors", "term": "Vectors", "aka": ["ballistic vectors", "arcs", "V"], "cat": "analysis", "def": "Arcs above the board for the engine lines' first moves: each is the jump the piece would make, from its crown to its target.", "game": "A quick picture of the candidate moves without reading a table.", "analysis": "Line 1 is cyan and bright; lines 2 to 5 are steel. A pulse runs along each arc from the launch ring at the piece's square.", "where": "Analyze: the Vectors toggle on the stage (or V). Palette: :vectors.", "go": "analyze", "see": ["multipv", "principal-variation", "phantoms"]},
  {"id": "tactical-xray", "term": "Tactical X-Ray", "aka": ["X-Ray", "xray", "hold Space", ":xray"], "cat": "analysis", "def": "A close look at one square in Analyze: a gauge ring on the board, and a readout docked beside the board with the square's numbers.", "game": "It answers \"what happens if I go there?\": the best move landing on the square, what it gives up against the best move overall, and who attacks and defends the square, piece by piece.", "analysis": "Read the ring like a dial from your side of the board, clockwise from the top. The arc is the expected score the best move onto the square gives up: cyan and a full circle when the best move of all lands there, ivory within 5 %, amber to 15 %, crimson beyond. Beads mark every piece bearing on the square, solid ivory for White and hollow steel for Black, each joined to its piece by a thread. The outer rim is the square's state: crimson and breathing when a piece there hangs, amber when it is outnumbered or attacked by something cheaper.", "engine": "The numbers come from the root move-value field (every legal move scored by a second engine); the attacker and defender counts come from the rules engine and ignore pins.", "where": "Analyze → X-Ray toggle on the stage (or X), or hold Space, which works right after a click on the rail. On a touch screen, with the X-Ray on, a tap on the board aims it and a second tap on the same square releases it. The readout docks at the board's left edge and moves right only when the square itself would sit under it.", "go": "analyze", "example": "e4, best move: Nxe4 lands here, the ring is a full cyan circle, the rim pulses crimson: the knight on e4 is attacked once and defended 0 times.", "see": ["root-multipv-field", "expected-score", "attackers-and-defenders", "hanging-piece"]},
  {"id": "synaptic-pv", "term": "Synaptic PV", "aka": ["PV scrubber", "syn", "line chips", "Play to here"], "cat": "analysis", "def": "The strip under the board in Analyze that lays every engine line out as chips, one per ply, with the fork walk's row beneath line 1.", "analysis": "Hover or focus a chip to see the line played out to that ply on the board (phantoms); click to hold it, or on a touch screen tap a move to pin its line. A pinned chip offers Play to here: the line goes onto the board as an explored line and the analysis carries on from where it leads, while the game itself does not change. Enter on the pinned chip or a double-click does the same, and Shift-click on a MultiPV row plays its first move. The root is the position at the playhead. While you read, the strip holds still and updates when you leave it.", "engine": "Lines come from the main search's MultiPV; the small scores on line 1's chips come from the fork walk, and amber chips mark an instability.", "where": "Analyze: the dock under the board, with its badges [SF: MultiPV] and [SF: fork walk · MultiPV 2], and a Mate note when a line has a mate.", "go": "analyze", "see": ["principal-variation", "phantoms", "fork-walk", "playhead"]},
  {"id": "phantoms", "term": "Phantoms", "aka": ["holograms", "ghosts", "preview"], "cat": "analysis", "def": "The board's preview of a scrubbed line, drawn as a difference: holograms where pieces land, faint ghosts where they leave, crimson ghosts for captured pieces.", "analysis": "Pieces that stay where they are stay solid, so only what changes stands out. Sweep along a line and the holograms glide from square to square, as if the line were being played.", "where": "Analyze: scrub the Synaptic PV, or hover a line.", "go": "analyze", "see": ["synaptic-pv", "vectors", "principal-variation"]},
  {"id": "fork-walk", "term": "Fork walk", "aka": ["fork", "walk", "◆ fork"], "cat": "analysis", "def": "A walk down line 1, asking at each of its first eight plies for the two best moves. The fork is the ply where the two are closest: the decision point of the line.", "analysis": "The fork row under line 1 shows each ply's second choice and its gap in expected score. A small gap means the line could easily go another way there.", "engine": "The field engine runs it after the field is done: MultiPV 2 at each node, to the fork walk depth (12 by default, 8 to 18 in UCI options).", "where": "Analyze: the Synaptic PV's fork row and its note. UCI options: Fork walk depth.", "go": "analyze", "example": "Reference: the fork at ply 6, a gap of 6.9 %.", "see": ["instability", "synaptic-pv", "expected-score", "principal-variation"]},
  {"id": "instability", "term": "Instability", "aka": ["unstable", "instab"], "cat": "analysis", "def": "A ply where the fork walk's first choice is not the move line 1 plays there.", "analysis": "The walk searches each node on its own, usually more shallowly than the main search did, so an instability means the line depends on depth there. Look at that ply before trusting the rest of the line.", "engine": "The trunk comes from the deep search; the walk from short searches on the field engine.", "where": "Analyze: amber chips on line 1 and an amber note in the Synaptic PV.", "go": "analyze", "example": "Reference: at ply 7 the walk prefers Ra7 to the trunk's Qc3.", "see": ["fork-walk", "depth", "synaptic-pv"]},
  {"id": "playhead", "term": "Playhead", "aka": ["current position", "root at playhead"], "cat": "analysis", "def": "The position the instruments are reading: wherever the move list, the review or the heartbeat has put the board.", "analysis": "Step the move list and Analyze follows: the Synaptic PV's root is the position at the playhead. In the Crucible, the heartbeat's playhead marks the ply shown on the board.", "where": "Analyze: the Synaptic PV (root at playhead). Crucible: the heartbeat.", "go": "analyze", "see": ["review", "synaptic-pv", "heartbeat"]},
  {"id": "search-profile", "term": "Search profile", "aka": ["profile"], "cat": "analysis", "def": "A small chart in Analyze of the search over time: depth climbing, and the hash filling.", "analysis": "Depth that stalls while hash nears full suggests a larger Hash; depth that rises in steady steps is a normal search.", "engine": "Drawn from the info stream, one point per report.", "where": "Analyze: Search profile, badged [SF: info stream].", "go": "analyze", "see": ["depth", "hashfull", "info-stream", "iterative-deepening"]},
  {"id": "reference-run", "term": "Reference", "aka": ["reference run", "Kasparov – Topalov", ":reference"], "cat": "analysis", "def": "Kasparov – Topalov, Wijk aan Zee 1999, after 24. Rxd4 cxd4, with Dennis's recorded Stockfish 19 run: 120 s, depth 26, the field at depth 16.", "analysis": "Load it to see every instrument on a famous position with known numbers: 25. Re7+ +1.40, Sharpness 45.2 %, one square lit. Readouts are badged as recorded until Go infinite starts a live search.", "engine": "The run is data/analyze.json beside the page; when it cannot be read, the page says why.", "where": "Analyze: Reference. Palette: :reference.", "go": "analyze", "example": "Line 1: 25. Re7+ Kb6 26. Qxd4+ Kxa5 27. b4+, +1.40, WDL 88 / 12 / 0.", "see": ["recorded-and-live", "sharpness", "root-multipv-field", "sacrifice"]},
  {"id": "source-badges", "term": "Source badges", "aka": ["badges", "[SF: UCI info]", "[Runner: GSPRT]", "rec", "Short source badges", ":badges short"], "cat": "analysis", "def": "The bracketed labels beside readouts that say where each number comes from: [SF: ...] from the engine, [Runner: ...] from the Crucible, [Browser: ...], [Renderer: ...], [Recorded: ...], [Data: ...].", "analysis": "They keep the instrument honest: a number is the engine's, the page's arithmetic, the browser's, or a recording. · rec or · recorded marks a value read from a file, not measured now. The short form, in Settings or with :badges short, names only the source: [SF: MultiPV 5 · d26 · recorded] reads [SF · rec], and the full badge shows on hover.", "where": "Analyze, Crucible and the telemetry footer. Settings, World and graphics: Short source badges. Palette: :badges short, :badges full. When the footer is tight, its badges shorten to the source ([SF]); the full text shows on hover.", "go": "analyze", "example": "[SF: MultiPV 5 · d26 · recorded]", "see": ["recorded-and-live", "telemetry", "uci"]},
  {"id": "recorded-and-live", "term": "Recorded and live", "aka": ["recorded run", "live run", "rec"], "cat": "analysis", "def": "Two kinds of numbers on the MONOLITH screens: recorded, read from Dennis's data files beside the page, and live, measured now by engines in your browser.", "analysis": "The Reference and the recorded Crucible are recorded; the page re-checks them (it recomputes the LLR trace, Elo and anomalies from the games). Everything else is live. Badges say which.", "engine": "The files are data/analyze.json and data/gauntlet.json. Live searches run on this device and differ from the recording in speed and sometimes in result.", "where": "Analyze: the Reference. Crucible: Recorded run and Live run.", "go": "crucible", "see": ["reference-run", "source-badges", "crucible", "results-json"]},
  {"id": "sharpness", "term": "Sharpness", "aka": ["MultiPV Dropoff", "halo", "Knife-edge", "Calm"], "cat": "analysis", "def": "How much worse the second and third best moves are than the best, in expected score for the side to move: line 1 to 2, and line 1 to 3.", "game": "A sharp position punishes the second-best move; a calm one forgives it.", "analysis": "At 10 % or more from line 1 to line 2 the halo comes on (Knife-edge); below it reads Calm. It is drawn as a halo on the WDL ribbon beside the board.", "engine": "It needs MultiPV of at least 2; with one line the chip says one line.", "where": "Analyze: the Sharpness section and the WDL ribbon.", "go": "analyze", "example": "Reference: 45.2 % from line 1 to 2, 56.4 % to 3, Knife-edge.", "see": ["expected-score", "multipv", "wdl", "root-multipv-field"]},
  {"id": "explore", "term": "Explore", "aka": ["Move pieces on any board", "Explore in Analyze", "scratch line", ":explore", ":explore analyze", "Free board", "Play from here"], "cat": "analysis", "def": "Trying your own moves without changing the game: on the free board before any game, an earlier move under review, a finished game, a Crucible game, or in Analyze at the live position of a game in progress. The moves go into a scratch line.", "game": "Click a piece on such a board and move it, or drag it. The chip says what you are exploring from; Undo steps back, Back returns. The game and the record never change. Before a game the free board takes both sides in turn from the starting position: the chip's Reset clears the line, and Play from here makes it a game that keeps its moves.", "analysis": "Analyze and the evaluation bar follow the explored position while it lasts. During a game, a move made in Analyze at the live position (a click, a drag or a typed move) starts a line from it, the chip reads Exploring from the live position, and the game does not change. With Explore in Analyze off, a move made there on your turn is played in the game.", "where": "Settings, Game: Move pieces on any board and Explore in Analyze (both on by default). Analyze: the Explore switch beside Field, Vectors and X-Ray. The Exploring chip on the stage (Free board before a game). Palette: :explore, :explore analyze, :explore back.", "go": "settings", "see": ["review", "playhead", "heartbeat"]},
  {"id": "review", "term": "Review", "aka": ["Viewing an earlier move", "Back to live", "stepping"], "cat": "analysis", "def": "Stepping back through the game without changing it.", "game": "Use the move list, its arrows, or ← →, Home and End. A chip says which move you are viewing; Back to live returns. The Coach shows what it said at that move.", "analysis": "Analyze searches whatever position you step to.", "where": "The move list and its buttons; the chip on the stage.", "example": "Viewing move 3… Nf6", "see": ["playhead", "explore", "coach"]},
  {"id": "hint", "term": "Hint", "aka": ["hints", "More help", "Show the move", ":hint"], "cat": "analysis", "def": "Help on your turn, given one step at a time: a nudge about the kind of move to look for, then the piece to move, then the move itself with its reason.", "game": "Press Hint for the nudge (\"There is a capture that works\"), More help to light the piece, Show the move for the arrow and the target square, and Hide hint to clear it. Stopping at the first or second step keeps most of the thinking yours.", "analysis": "The nudge names what the engine's best move does: wins material, captures, checks, uncovers a discovered attack, springs a trap, creates a threat, defends, castles, develops, or a quiet improvement. It never claims more than the move does.", "engine": "The hint uses the Coach's lines for the position when they are ready, otherwise a search of its own to depth 12 within 1.5 seconds.", "where": "Play → the turn card, beside Undo; the steps appear under Your move. The H key. Palette: :hint.", "go": "play", "example": "Something can be won here. → The pawn on e4 has the move. → Play exd5. It wins a knight and attacks the knight on c6.", "see": ["coach", "best-line", "calculate-moves"]},
  {"id": "calculate-moves", "term": "Calculate moves", "aka": ["candidates", "candidate moves", ":calc"], "cat": "analysis", "def": "The engine's best moves for the position shown, drawn as ranked arrows on the board and listed with their scores.", "game": "Choose how many Lines (1 to 5) and press Calculate moves. Arrows take their grade's colour; select a line to isolate its arrow. On your own turn it is the engine's answer, so it teaches most after you have chosen your move.", "analysis": "Each line is graded against the best in centipawns (see Move grades).", "engine": "The play engine, MultiPV as chosen, to depth 16 within 3 seconds.", "where": "Play: Coach card, Engine lines. Palette: :calc.", "go": "play", "example": "Top 3 at depth 16.", "see": ["move-grades", "multipv", "hint", "best-line"]},
  {"id": "coach", "term": "Coach", "aka": ["coach comments", "coach notes", "the Coach"], "cat": "analysis", "def": "The Coach reads your game as it is played: a verdict on each of your moves, a reading of each of the opponent's moves, a watch on your turn, hints in steps, and a review when the game ends. Everything it says comes from a dataset of its own lines, filled with facts the page has checked.", "game": "After your move you get a grade (Book, then Best to Blunder, with Brilliant for a sound sacrifice) with what the move does and, after a slip, the better move and what it changes. On your turn it warns of check, threats of mate or material, loose pieces, a slip by the computer you can punish, a repetition, the fifty-move count or a stalemate trap, or offers a tip that fits the board. Opening habits are mentioned once a game, and only when the engine did not prefer the move anyway.", "analysis": "The notes stay with their moves: step back through the move list and the Coach shows what it said there. The move list carries ?!, ? and ?? for inaccuracies, mistakes and blunders, ! for an only move or a mate found, !! for a brilliant move. At the end, the review gives each coached side's accuracy (lichess's formula), its inaccuracies, mistakes and blunders, and two buttons for the move where the game turned: Show, which goes there on this board, and Analyze it, which opens it in Analyze.", "engine": "The Coach runs its own Stockfish beside the one you play (32 MB hash): MultiPV 3 to depth 12 within 1.5 seconds for each of your positions, and a search for your own move if it was not among those lines. For threats it hands the move to the opponent (a null move) and asks what it would play. Opening names come from the lichess opening list.", "where": "Play → Coach card, with Comments on or off in its header and the engine lines folded underneath; the opening line on the turn card. Settings, Game: Coach comments. Palette: :coach.", "go": "play", "example": "Your 2. Qh5 is graded Inaccuracy: \"A small slip. Qh5 puts the question to the pawn on e5, but Nf3 brings the knight into play.\"", "see": ["coach-grades", "accuracy", "hint", "book-move", "expected-score"]},
  {"id": "crucible", "term": "Crucible", "aka": ["gauntlet", "Match", "engine match"], "cat": "testing", "def": "A match between two engine configurations, A and B, played in pairs of games until a sequential test decides which is stronger, or a fixed number of pairs is done.", "analysis": "The recorded run is Stockfish 19 at 3,000 nodes a move against 2,000: 45 pairs, H1 accepted at LLR 2.99, A +185.7 Elo, 95 % interval 129.5 to 252.6. Live runs play in your browser with your settings. The verdict reads as a sentence, such as \"A is stronger than B: +185.7 Elo, 95 % from +129.5 to +252.6.\"", "engine": "Each game slot runs two Stockfish workers, one for A and one for B, so they never share a hash table. Leaving the tab does not stop a live run.", "where": "Crucible tab: Recorded run or Live run; Deck (LLR and Hive) or Board (one game, which the Moves card lists and steps). Before a live run the deck says what to do next and has its own Start run. Palette: :recorded, :sprt start, :sprt stop.", "go": "crucible", "see": ["sprt", "gsprt", "game-pair", "elo", "hive"]},
  {"id": "sprt", "term": "SPRT", "aka": ["sequential probability ratio test", "sequential test"], "cat": "testing", "def": "The Sequential Probability Ratio Test: play games until the evidence is strong enough to accept one of two hypotheses about the Elo difference, then stop.", "analysis": "It stops as early as the results allow: a big difference decides in a few dozen games, a small one needs thousands.", "engine": "Engine developers test every change this way; the Crucible uses the pentanomial form (GSPRT) over game pairs.", "where": "Crucible: the SPRT section, the stopping rule SPRT or Fixed pairs, the oscilloscope.", "go": "crucible", "see": ["gsprt", "llr", "hypotheses", "sprt-bounds"]},
  {"id": "gsprt", "term": "GSPRT", "aka": ["generalized SPRT", "pentanomial GSPRT"], "cat": "testing", "def": "The generalized SPRT: the sequential test computed from the mean and variance of the pair scores rather than from a model of single games.", "analysis": "Counting pairs rather than games takes the colour advantage and the opening's bias out of the noise, so tests decide sooner.", "engine": "LLR = n (s1 − s0) (2 mean − s0 − s1) / (2 variance), with s0 and s1 the expected pair scores at elo0 and elo1 (logistic Elo), over n pairs. It stays 0 while the pair variance is zero.", "where": "Crucible: [Runner: GSPRT] badges; the LLR oscilloscope.", "go": "crucible", "see": ["llr", "pentanomial", "game-pair", "hypotheses"]},
  {"id": "llr", "term": "LLR", "aka": ["log-likelihood ratio"], "cat": "testing", "def": "The log-likelihood ratio: how much more likely the results so far are under H1 than under H0. Positive favours H1.", "analysis": "The test stops when the LLR crosses a bound: the upper accepts H1, the lower accepts H0. Between them, keep playing.", "where": "Crucible: the SPRT section, the oscilloscope, the footer's LLR cell (value / upper bound).", "go": "crucible", "example": "2.99 / 2.94: the recorded run has just crossed the upper bound.", "see": ["sprt-bounds", "llr-oscilloscope", "gsprt"]},
  {"id": "sprt-bounds", "term": "SPRT bounds", "aka": ["bounds", "accept", "reject"], "cat": "testing", "def": "The two LLR levels that end the test: ln((1 − β) / α) above, ln(β / (1 − α)) below.", "analysis": "With α = β = 0.05 they are ±2.94. Tighter error rates widen them and make the test longer.", "where": "Crucible: the SPRT section; dashed lines on the oscilloscope.", "go": "crucible", "example": "α = β = 0.01 gives ±4.60.", "see": ["error-rates", "llr", "sprt"]},
  {"id": "hypotheses", "term": "Hypotheses", "aka": ["H0", "H1", "elo0", "elo1"], "cat": "testing", "def": "The two claims the test decides between: H0, that A is elo0 stronger than B, and H1, that A is elo1 stronger.", "analysis": "The defaults are 0 and 10: is A no better, or at least 10 Elo better? Accepting H1 does not measure the difference; the Result section estimates that.", "where": "Crucible: Live run, Elo, elo0 and elo1.", "go": "crucible", "see": ["sprt", "error-rates", "elo"]},
  {"id": "error-rates", "term": "Error rates", "aka": ["α", "β", "alpha", "beta"], "cat": "testing", "def": "α is the chance of accepting H1 when H0 is true; β the chance of accepting H0 when H1 is true. The Crucible sets them equal.", "analysis": "0.05 is the usual choice; 0.01 is stricter and slower; 0.10 faster and looser.", "where": "Crucible: Live run, α = β (0.05, 0.10 or 0.01).", "go": "crucible", "see": ["sprt-bounds", "hypotheses"]},
  {"id": "elo", "term": "Elo", "aka": ["rating", "Elo difference", "Result"], "cat": "testing", "def": "A rating scale where a difference predicts an expected score: 0 is even, +100 about 64 %, +200 about 76 %.", "analysis": "The Crucible turns A's mean pair score into Elo with the logistic formula, −400 log10(1 / s − 1), and shows it from A's view with a 95 % interval.", "engine": "These are match Elo between two configurations, not ratings against people.", "where": "Crucible: Result, with the interval bar.", "go": "crucible", "example": "+185.7, interval 129.5 to 252.6, in the recorded run.", "see": ["confidence-interval", "hypotheses", "uci-elo"]},
  {"id": "confidence-interval", "term": "Confidence interval", "aka": ["CI", "95 %", "interval"], "cat": "testing", "def": "A range that would contain the true value 95 times in 100: here, the Elo difference between A and B.", "analysis": "The Crucible uses the mean pair score plus or minus 1.96 standard errors, mapped to Elo; the bar shows it against 0. An interval clear of 0 means a real difference.", "where": "Crucible: Result, the interval and its bar.", "go": "crucible", "example": "129.5 to 252.6 in the recorded run.", "see": ["elo", "pentanomial", "game-pair"]},
  {"id": "pentanomial", "term": "Pentanomial", "aka": ["LL LD DD+WL WD WW", "pair counts"], "cat": "testing", "def": "The five possible results of a game pair, from A's side: LL (lost both), LD, DD or WL (one point), WD, WW (won both).", "analysis": "Counting pairs this way is what the GSPRT and the interval are built on. Many WL pairs mean the openings favour one colour strongly.", "where": "Crucible: Result, Pentanomial.", "go": "crucible", "example": "Recorded run: 0 · 3 · 10 · 17 · 15.", "see": ["game-pair", "gsprt", "confidence-interval"]},
  {"id": "game-pair", "term": "Game pair", "aka": ["pairs", "paired openings", "colours swapped"], "cat": "testing", "def": "Two games from the same opening, with A and B swapping colours. A pair scores 0, 0.25, 0.5, 0.75 or 1 for A.", "analysis": "Pairing cancels the opening's bias and White's first-move edge. Fixed pairs plays a set number of pairs (two games each) instead of testing.", "where": "Crucible: Pairs (Fixed pairs), the pair strip under the oscilloscope.", "go": "crucible", "see": ["pentanomial", "gsprt", "crucible"]},
  {"id": "anomaly", "term": "Anomaly", "aka": ["anomalies", "crash ply"], "cat": "testing", "def": "A game the Crucible flags because one engine's own evaluation went from balanced (within 1.50) to decisive (5.00 or more) between two of its moves.", "analysis": "The cause is usually the other engine's move in between, a blunder that a short search did not see. Open the game from the list and the heartbeat marks the slot.", "engine": "Each engine's evals are compared two plies apart, from White's view; the move one ply before the jump is named as the cause.", "where": "Crucible: Anomalies (9 in the recorded run), crimson tiles in the Hive, the heartbeat.", "go": "crucible", "example": "Game 78: 48. Bxc3, +0.93 to +7.47.", "see": ["heartbeat", "swing", "hive"]},
  {"id": "adjudication", "term": "Adjudication", "aka": ["adjudicated win", "adjudicated draw"], "cat": "testing", "def": "Ending an engine game early when the result is clear, to save time.", "analysis": "In the Crucible: a win when |eval| is 10.00 or more for 4 plies in a row, a draw when |eval| stays within 0.10 for 10 plies after ply 80, and a draw at ply 240. Mate, stalemate, repetition, the fifty-move rule and insufficient material end games as usual.", "where": "Crucible: the Adjudication section; each game's termination.", "go": "crucible", "example": "Recorded run: 60 adjudicated wins, 11 adjudicated draws.", "see": ["pawn-units", "draw", "crucible"]},
  {"id": "nodes-per-move", "term": "Nodes per move", "aka": ["node limit", "nodes 3000"], "cat": "testing", "def": "A search limit by work, not time: the engine stops after a set number of nodes for each move.", "analysis": "It makes a match repeatable on any device, which time limits are not. More nodes, stronger play: the recorded run tests 3,000 against 2,000.", "engine": "UCI go nodes 3000. The Crucible accepts 100 to 2,000,000.", "where": "Crucible: Live run, Stockfish 19 · nodes per move.", "go": "crucible", "see": ["nodes", "search-limit", "crucible"]},
  {"id": "llr-oscilloscope", "term": "LLR oscilloscope", "aka": ["oscilloscope", "LLR trace"], "cat": "testing", "def": "The Crucible's chart of the LLR after each pair, between the two dashed bounds.", "analysis": "Cyan above zero, crimson below; the regions past the bounds are tinted. The strip under it shows each pair: up for a pair A won, down for one it lost, a dot for a split.", "where": "Crucible: Deck, LLR oscilloscope, badged [Runner: GSPRT].", "go": "crucible", "see": ["llr", "sprt-bounds", "game-pair"]},
  {"id": "hive", "term": "The Hive", "aka": ["Hive", "final positions"], "cat": "testing", "def": "A grid of every game's final position in the match, each tile with its result and a small heartbeat.", "analysis": "The legend reads 1–0, ½, 0–1 and anomaly. Select a tile to open that game on the 3D board.", "where": "Crucible: Deck, The Hive.", "go": "crucible", "see": ["heartbeat", "anomaly", "crucible"]},
  {"id": "heartbeat", "term": "Heartbeat", "aka": ["eval trace", "move rail"], "cat": "testing", "def": "A Crucible game's evaluation through the game, from White's view, over a rail with a slot for every ply.", "analysis": "White's moves sit in the upper lane, Black's in the lower. Book moves are plain; engine moves are shaded by their swing, amber from 1.00 and crimson from 3.00. Hover a slot to read the move; click, drag or use the arrow keys to go there.", "engine": "The evals are each engine's own score for its move, so the trace alternates between two searches.", "where": "Crucible: Board view, the dock under the board. Its drag handle sets its height.", "go": "crucible", "see": ["swing", "anomaly", "playhead", "drag-handles"]},
  {"id": "parameter-matrix", "term": "UCI parameter matrix", "aka": ["matrix", "parameters"], "cat": "testing", "def": "A table of A's and B's settings side by side: engine, build, limit per move, hash and threads.", "analysis": "Raised fields differ between A and B: what the match is actually testing.", "where": "Crucible: UCI parameter matrix.", "go": "crucible", "see": ["uci-options", "crucible", "nodes-per-move"]},
  {"id": "results-json", "term": "Results JSON", "aka": ["Copy results JSON", "crucible-run.json"], "cat": "testing", "def": "The match as a data file: configurations, the SPRT settings and trace, the result with its pentanomial and interval, and every game with its moves, evals and termination.", "analysis": "Copy results JSON puts it on the clipboard in the same shape as the recorded gauntlet, so a live run can be kept or compared.", "where": "Crucible: Adjudication, Copy results JSON (once a game is done).", "go": "crucible", "see": ["recorded-and-live", "crucible", "pgn"]},
  {"id": "parallel-games", "term": "Parallel games", "aka": ["Parallel", "GAMES", "games at once"], "cat": "testing", "def": "How many Crucible games play at once.", "analysis": "Up to four, and never more than the device's cores minus one. Each slot runs two engines, so four slots is eight workers.", "engine": "Games in parallel share the processor; nodes per move keeps the result independent of that, time limits do not.", "where": "Crucible: Live run, Parallel. The footer's GAMES cell (games done, games per minute).", "go": "crucible", "see": ["threads", "nodes-per-move", "telemetry"]},
  {"id": "command-palette", "term": "Command palette", "aka": ["palette", "Ctrl K", "⌘K"], "cat": "interface", "def": "A search box for every action in the app, opened with Ctrl K (⌘K on Apple keyboards) or the >_ button.", "game": "Type a few letters of what you want: :hint, :undo, :flip, :new, or an everyday word such as take back, mute or give up. A command that cannot run now is greyed, with the reason, and a word no command knows, such as castling, opens its Grimoire entry.", "analysis": "Some take an argument: :fen followed by a FEN opens it in Set up (in Analyze, it is analysed there); :define followed by a term opens it in the Grimoire.", "where": "The >_ button at the foot of the rail, over Flip board, Sound and the version chip; under 900 px wide, at the end of the app bar.", "example": ":define hashfull", "see": ["grimoire", "version-chip", "fen"]},
  {"id": "worlds", "term": "Worlds", "aka": ["Cathedral", "Monolith", "World"], "cat": "interface", "def": "The two settings the board lives in: the cathedral for play and MONOLITH for the instrument.", "game": "On Auto the world follows the tab: the cathedral for Play and Position, MONOLITH for Analyze and Crucible. The Grimoire keeps whichever you were in.", "analysis": "Materials, lights and backdrop blend across a short transition; the sets swap under a dip.", "where": "Settings, World and graphics: World (Auto, Cathedral, MONOLITH). Palette: :world auto, :world cathedral, :world monolith.", "go": "settings", "see": ["monolith", "graphics-tiers", "flip-board"]},
  {"id": "graphics-tiers", "term": "Graphics levels", "aka": ["Graphics", "Graphics tiers", "Ultra", "High", "Medium", "Low", "Minimal", "Automatic", "Auto", "Custom", "Fine-tune", "Balanced", "quality"], "cat": "interface", "def": "Five levels of rendering, Minimal to Ultra, each adding to the one below. Automatic picks one for the device, and Fine-tune sets each part yourself.", "game": "Minimal draws straight to the screen and needs no WebGL 2. Low adds HDR, multisampling and bloom. Medium (once called Balanced) adds light ray-marched at quarter resolution, a soft mirror floor in MONOLITH and 1.5× resolution. High marches the light at half resolution, with a sharp mirror, 2048 px shadows and 2× resolution; Ultra at three-quarter resolution in 56 steps, with a full-resolution mirror and 4096 px shadows.", "analysis": "Automatic starts from the GPU the browser names (software rendering, a phone or tablet, integrated graphics, Apple silicon or a graphics card) and watches the frames in 3-second stretches: two slow ones in a row (under 28 fps) lower the level, four quick ones (over 50 fps) raise it, never back to a level it had to leave. Under Graphics it says what it chose and why.", "engine": "The engines do not depend on it, though a heavy level competes with them for the processor on slow devices, and Automatic reads that as slow frames.", "where": "Settings, World and graphics: Graphics (Automatic, the five levels, Fine-tune). Palette: :quality. The footer's RENDER and GPU cells.", "go": "settings", "see": ["worlds", "telemetry"]},
  {"id": "telemetry", "term": "Telemetry", "aka": ["footer", "NPS", "FRAME", "RENDER", "WORKERS", "HEAP", "GPU", "HOST", "SENSORS"], "cat": "interface", "def": "The footer along the bottom of MONOLITH: live readouts from the engine, the runner, the browser and the renderer, each with its source badge.", "analysis": "NPS, HASH and TB HITS follow the search (Analyze's, or the play engine's); GAMES and LLR follow the Crucible; FRAME, RENDER, WORKERS, HEAP and GPU describe this browser. HOST and SENSORS appear only with a recording that has them.", "engine": "A page cannot read CPU load or temperatures, so those come only from recordings, marked [Recorded: ...].", "where": "The bottom of the screen in MONOLITH. When it is tight it compacts its badges, then sets the least telling readouts aside. Screens under 900 px wide set the footer aside; there the engine card and the Crucible's pane carry its readings.", "go": "analyze", "see": ["source-badges", "nps", "hashfull", "graphics-tiers"]},
  {"id": "flip-board", "term": "Flip board", "aka": ["flip", "invert", ":flip"], "cat": "interface", "def": "Turning the board to view it from the other side.", "game": "The flip button at the foot of the rail (at the end of the app bar under 900 px wide), Flip board in Settings (Board), the F key on Play and Position, or :flip. Your pieces start at the bottom; flipping turns the view, never the game. In a friend game whose board turns for each player, a flip holds for the move on the board, and the next move turns it again.", "analysis": "The world turns with the camera, lights and reflections included, so the backdrop holds still behind the board.", "where": "The foot of the rail, or the app bar under 900 px wide; Settings, Board; the F key (Play, Position); palette.", "see": ["ranks-and-files", "worlds", "auto-flip"]},
  {"id": "auto-flip", "term": "Turn the board for each player", "aka": ["auto-flip", "autoflip", ":autoflip", "Turns each move", "hotseat", "pass and play"], "cat": "interface", "def": "In a game between two people on one screen, the board turns after each move so that the side to move sits at the bottom.", "game": "On by default. A beat after a move lands, the board turns to the side to move; under Minimal animation or reduced motion it is a cut. Undo and Back to live turn it at once, stepping through earlier moves leaves it still, and Flip board holds for the move on the board. Games against the computer, puzzles and practice studies are not turned.", "where": "Play: the setup's Your pieces card when Friend is chosen, and the Board card in a friend game (Turns each move). Settings, Board. Palette: :autoflip.", "go": "settings", "see": ["flip-board", "side-to-move", "draw"]},
  {"id": "version-chip", "term": "Version chip", "aka": ["version", ":version", "v2.3.0"], "cat": "interface", "def": "The small label at the foot of the rail, under the palette, Flip and Sound buttons, that names the release this copy of the page is.", "game": "If it shows a lower number than the published page, your copy is behind.", "where": "The foot of the rail; under 900 px wide, a line under the MONOLITH wordmark instead. Settings, Help and about. Palette: :version.", "example": "v2.3.0", "see": ["command-palette", "grimoire"]},
  {"id": "drag-handles", "term": "Drag handles", "aka": ["splitters", "resize"], "cat": "interface", "def": "Grips between the parts of the screen that resize them: the dock, the side panel and the move list.", "game": "Drag to resize; arrow keys step a focused handle; Home or a double-click resets it. The side panel's width is kept per world, the other sizes per tab.", "where": "The edge of the side panel, the top of the move list, the top of the dock (in Crucible, the heartbeat's height).", "see": ["heartbeat", "synaptic-pv"]},
  {"id": "tips", "term": "Tips", "aka": ["hints on screen", "Show tips again"], "cat": "interface", "def": "Short coaching texts on the board and panels: how to select a piece, how to castle, how to orbit the camera.", "game": "Until used hides each tip once you have done what it says; Always keeps them; Off hides them. Status text such as check or thinking always shows.", "where": "Settings, Help and about: Tips, and Show tips again. Palette: :tips.", "go": "settings", "see": ["coach", "hint"]},
  {"id": "grimoire", "term": "Grimoire", "aka": ["reference", "glossary", "wiki", ":define", ":grimoire"], "cat": "interface", "def": "This reference: every term on these screens, with what it means, how it reads in a game, in analysis and inside the engine, and where it is in MONOLITH.", "game": "A dotted underline marks a term anywhere in the app. Click it for a short card, and Open in Grimoire for the full entry.", "analysis": "Search by name or by any other name it goes by; filter by category; step through with the arrows; See also links related terms.", "where": "The Grimoire tab. / focuses its search. Palette: :grimoire, or :define followed by a term.", "go": "grimoire", "example": ":define hashfull", "see": ["command-palette", "coach", "hashfull"]},
  {"id": "coach-grades", "term": "Coach grades", "aka": ["verdicts", "Book", "Brilliant", "Best", "Excellent", "Good", "Inaccuracy", "Mistake", "Blunder", "Only move", "Missed win", "Allows mate", "!!", "?!", "??"], "cat": "eval", "def": "The Coach grades each of your moves by the expected score it gives up against the engine's best move: Best (none), Excellent (under 2 %), Good (under 5 %), Inaccuracy (under 10 %), Mistake (under 20 %), Blunder (20 % or more). A move from the opening list that is not a slip is graded Book.", "game": "Grading by expected score rather than pawns means the same slip counts for more in a balanced position than in one already won or lost, which is how a game actually turns. Only move marks the best move when every other gives up 20 % or more. Brilliant marks a sacrifice of two points or more that the engine stands behind, when you were not already winning easily. Mates follow lichess's rules: letting a forced mate go, or allowing one, is graded by how much the position still holds.", "analysis": "The bands are chess.com's, and the curve from score to expected score is lichess's. The move list shows ?! for an inaccuracy, ? for a mistake, ?? for a blunder, ! for an only move or a found mate and !! for a brilliant move. Calculate moves grades its candidate arrows differently, in centipawns (see Move grades).", "engine": "Expected score comes from the engine's score through the logistic 1 / (1 + e^(−cp / 271.6)); a forced mate counts as a full point. Allowing a mate is a blunder unless the mover already stood at −7.00 (then a mistake) or −10.00 (an inaccuracy); letting one go is graded the same way by what remains.", "where": "Play → Coach card (the badge on each verdict) and the move list's marks.", "go": "play", "example": "A move that drops the expected score from 55 % to 41 % gives up 14 %: a Mistake, marked ?.", "see": ["coach", "expected-score", "accuracy", "move-grades", "annotation-symbols"]},
  {"id": "match-strip", "term": "Match strip", "aka": ["app bar", "header status", "move counter"], "cat": "interface", "def": "The pill at the right end of the app bar that says what the board is showing: the players with the side to move ringed, the move number and what is happening now, and the last move.", "game": "In a game it reads, for example, You (Marble) vs Stockfish (Club · 4/8), Move 12, Your move, Last 11…Nf6; it turns to Stockfish thinking, check, or the result as they happen. Before a game, moves tried on the board show as Free board with their line.", "analysis": "In Analyze it names the position (live game, earlier position, explored line or the reference), the move and side to move, and the evaluation from White's side with the depth and the search state under it; in Crucible, the two engines, the games played and the verdict.", "where": "App bar, at its right end. In a narrower window the levels go first (under 1100 px wide), then the last move (under 1000 px); the players, or the title, and the move stay at every desktop width. Under 900 px wide it leaves the job to the panel.", "see": ["move-number", "side-to-move", "telemetry"]},
  {"id": "book-move", "term": "Book move", "aka": ["book", "theory", "known line"], "cat": "tactics", "def": "A move that reaches a named position in the opening list: established theory rather than a fresh idea.", "game": "The Coach grades such a move Book and names the opening when it changes. A known line the engine dislikes still gets its own grade, with a note that it is known but not trusted.", "analysis": "Book is not a promise of quality. Lines are named because they are played, and some are named because they are traps.", "engine": "The book is the lichess-org chess-openings list (public domain, CC0): about 3,900 named positions, matched by position, so transpositions find their names.", "where": "Play: the Coach's Book grade and the opening line on the turn card.", "go": "play", "example": "1. e4 e5 2. Nf3 Nc6 3. Bc4 is Book: the Italian Game.", "see": ["opening", "eco", "coach-grades", "gambit"]},
  {"id": "eco", "term": "ECO code", "aka": ["ECO", "Encyclopaedia of Chess Openings", "opening code", "opening name", "C50"], "cat": "notation", "def": "A letter and two digits, A00 to E99, that classify an opening, from the Encyclopaedia of Chess Openings. Openings also carry names, family first: Italian Game: Giuoco Piano.", "game": "The turn card shows the code and the name of the opening the game is in, and keeps the last named position once the game leaves the list. The Coach names the opening when the game enters a new one.", "analysis": "Codes group openings by their first moves: A flank openings, B semi-open games other than the French, C the French and open games, D closed games, E Indian defences.", "engine": "The names and codes come from the lichess-org chess-openings list (public domain, CC0), matched by position, so a transposition finds its name.", "where": "Play: the opening line on the turn card; the Coach's Book notes. Analyze: the Reference is B07. Position, Read: Rules, the opening's name.", "go": "play", "example": "C50 · Italian Game, after 1. e4 e5 2. Nf3 Nc6 3. Bc4.", "see": ["opening", "book-move", "san"]},
  {"id": "accuracy", "term": "Accuracy", "aka": ["accuracy %", "game accuracy", "review"], "cat": "eval", "def": "A score from 0 to 100 % for how closely a side's moves kept the expected score the engine saw, over a whole game.", "game": "When a game ends, the Coach gives the accuracy of each side it coached, counts the inaccuracies, mistakes and blunders, and names the turning point with a button that shows it on the board.", "analysis": "Each move scores 100 % when it keeps the win chance, falling steeply as it gives chance away (64.6 % for a 10-point drop). The game figure is the mean of a volatility-weighted mean and a harmonic mean, so one blunder weighs more than many small slips, and quiet stretches count less.", "engine": "This is lichess's published formula: 103.1668 e^(−0.04354 d) − 3.1669 + 1 for a drop of d points in win chance, with weights from the spread of win chances over a sliding window. The win chances come from the Coach's own depth-12 searches, so figures differ from a site that analyses deeper.", "where": "Play: the Coach's Game over note.", "go": "play", "example": "Marble: 89 % accuracy, 1 inaccuracy, no mistakes and no blunders. Obsidian: 19 % accuracy, no inaccuracies, no mistakes and 1 blunder.", "see": ["coach-grades", "expected-score", "blunder", "coach"]},
  {"id": "passed-pawn", "term": "Passed pawn", "aka": ["passer", "passed pawns", "free pawn"], "cat": "tactics", "def": "A pawn with no enemy pawn in front of it or on either neighbouring file all the way to its queening square. Only pieces can stop it.", "game": "A passed pawn is a candidate for a queen, and the further it has run the more it is worth. The Coach notes when a move creates or pushes one; in endgames its tip is to push yours and stop theirs.", "analysis": "Passed pawns are what most endgames are about: a protected or outside passer often decides. Rooks belong behind them, yours or the opponent's.", "engine": "NNUE weighs passed pawns by rank and by what can stop them; deep searches see the race to queen.", "where": "Position, Read: Structure, the Passed chip (point at it to light the pawns on the map and the board). The Coach's notes.", "go": "position", "example": "White pawn on d5, black pawns only on the a, b, g and h files: d5 is passed.", "see": ["isolated-pawn", "promotion", "endgame", "open-file"]},
  {"id": "isolated-pawn", "term": "Isolated pawn", "aka": ["isolani", "isolated pawns", "IQP"], "cat": "tactics", "def": "A pawn with no friendly pawn on either neighbouring file, so no pawn can ever defend it.", "game": "It needs pieces to guard it, and the square in front of it is a good home for an enemy piece. In return the files beside it are open for your rooks.", "analysis": "An isolated d-pawn (the isolani) gives active play in the middlegame and becomes a weakness in the endgame: trade pieces against it, keep them on with it.", "where": "Position, Read: Structure, the Isolated chip.", "go": "position", "see": ["doubled-pawns", "passed-pawn", "open-file"]},
  {"id": "doubled-pawns", "term": "Doubled pawns", "aka": ["doubled", "double pawns"], "cat": "tactics", "def": "Two pawns of one colour on the same file, one in front of the other.", "game": "The front pawn blocks the back one, and they cannot defend each other. They often come from a capture toward the centre, which opens a file in return.", "analysis": "Doubled pawns are a long-term weakness, mostly in endgames; in the middlegame the open file and the extra control of squares can make up for them.", "where": "Position, Read: Structure, the Doubled chip.", "go": "position", "see": ["isolated-pawn", "open-file", "material"]},
  {"id": "open-file", "term": "Open file", "aka": ["open files", "half-open file", "semi-open file"], "cat": "tactics", "def": "A file with no pawns on it. A half-open file has no pawns of one side, only the opponent's.", "game": "Rooks and queens want open files: from there they reach the seventh rank and the enemy king. The Coach notes a rook that takes one, and in the middlegame its tip points to an open file when you have a rook to put there.", "analysis": "A half-open file points at an enemy pawn: pressure on it is a plan in itself.", "where": "Position, Read: Structure, the Open files chip (point at it to light the files), with the half-open files tinted lighter on the map.", "go": "position", "see": ["passed-pawn", "king-safety", "middlegame"]},
  {"id": "bishop-pair", "term": "Bishop pair", "aka": ["two bishops", "the pair", "opposite-coloured bishops"], "cat": "tactics", "def": "Both bishops, one on each colour of square. Together they cover the whole board, which a bishop and a knight cannot.", "game": "In open positions the pair is worth about half a pawn: keep it, and trade the opponent's pair away when you can. With one bishop each on opposite colours, endgames often end drawn, because the bishops never meet.", "analysis": "The Read view of the Position tab says who has the pair, or that the bishops are on opposite colours.", "where": "Position, Read: Structure, the Bishops chip. The Coach notes a move that wins the pair or gives it away.", "go": "position", "see": ["material", "endgame", "piece-values"]},
  {"id": "opposition", "term": "Opposition", "aka": ["the opposition", "taking the opposition"], "cat": "tactics", "def": "Two kings on the same file or rank with one square between them. The side not to move \"has the opposition\": the other king must give way.", "game": "In king and pawn endings the opposition decides: the attacker uses it to walk the king forward, the defender to stand in front of the pawn and hold. It also mates with a rook: with the kings face to face, a rook check drives the king back.", "analysis": "Distant opposition (three or five squares apart) works the same way at range.", "where": "Position, Studies: King and pawn: the king leads; King and pawn: hold the draw; Rook and king against king.", "go": "position", "example": "White king e4 and pawn e3, Black king e6, White to move: Black has the opposition and holds the draw.", "see": ["zugzwang", "endgame", "promotion"]},
  {"id": "lucena-position", "term": "Lucena position", "aka": ["Lucena", "building a bridge"], "cat": "tactics", "def": "The basic winning position in rook and pawn against rook: the pawn on the seventh, its king in front of it, the defending king cut off by a file.", "game": "The method is called building a bridge: check to push the defending king one file further, lift the rook to the fourth rank, walk the king out, and block the last check with the rook.", "analysis": "Most rook endings with an extra pawn are won by reaching the Lucena, or drawn because the defender reached the Philidor first.", "engine": "Stockfish finds the win quickly; the browser build has no tablebases, so it searches it.", "where": "Position, Studies: Lucena position (Endgames).", "go": "position", "example": "White Kb8, pawn b7, rook c1; Black Kd8, rook a2. 1. Rd1+ Ke7 2. Rd4 and the king comes out.", "see": ["philidor-position", "endgame", "promotion"]},
  {"id": "philidor-position", "term": "Philidor position", "aka": ["Philidor", "third-rank defence", "sixth-rank defence"], "cat": "tactics", "def": "The basic drawing position in rook and pawn against rook: the defending king on the queening square, its rook on the sixth rank (its own third) to keep the attacking king out.", "game": "Hold the rook on that rank until the pawn advances to it; then the attacking king has lost its shelter, and the rook goes to the back to check from behind.", "analysis": "Named after François-André Danican Philidor, who published it in 1777.", "where": "Position, Studies: Philidor position (Endgames), where you defend.", "go": "position", "example": "White Kd5, pawn e5, rook h7; Black Ke8, rook b6, White to move: a draw with the rook kept on the sixth rank.", "see": ["lucena-position", "draw", "endgame"]},
  {"id": "back-rank-mate", "term": "Back-rank mate", "aka": ["back rank", "back-rank weakness", "corridor mate"], "cat": "tactics", "def": "Mate by a rook or a queen on the last rank, against a king hemmed in by its own pawns.", "game": "Give your castled king air (a pawn move such as h3) once the heavy pieces come out, and watch the opponent's back rank for the same weakness. A defender of the back rank can often be drawn away with a sacrifice.", "analysis": "The Coach names a back-rank mate when it happens.", "where": "Position, Studies: Back-rank mate and Back rank: remove the guard (Mating patterns).", "go": "position", "example": "Rook on a1, black king g8 behind pawns f7 g7 h7: Ra8#.", "see": ["checkmate", "sacrifice", "smothered-mate"]},
  {"id": "smothered-mate", "term": "Smothered mate", "aka": ["smothered", "Philidor's legacy"], "cat": "tactics", "def": "Mate by a knight against a king whose every escape square is filled by its own pieces.", "game": "Corners are where it happens: a king on h8 behind pawns on g7 and h7, with a rook on g8. A queen sacrifice on g8 often forces the rook there first.", "analysis": "The Coach names a smothered mate when it happens.", "where": "Position, Studies: Smothered mate (Mating patterns).", "go": "position", "example": "Qg8+ Rxg8 Nf7#.", "see": ["checkmate", "fork", "back-rank-mate"]},
  {"id": "studies", "term": "Studies", "aka": ["study", "lessons", "puzzles", "practice"], "cat": "analysis", "def": "The Position tab's lessons: positions with a goal, each checked with Stockfish before it went in.", "game": "Puzzles ask for the moves: a wrong one is taken back, the replies come from the solution, and hints come one at a time. Practice games are played out against Stockfish at full strength and judged by their goal: mate, queen the pawn, or hold the draw. Set-ups load with Play's own settings, and the Castling drill as a game where you move both sides.", "analysis": "Each study says what it teaches and links to the Grimoire. Solved studies get a tick and are kept in this browser; a study solved after showing the solution is not counted.", "engine": "In practice games Stockfish plays at level 8 (Maximum) for that game only; your saved level is not changed. A hold is confirmed by the Coach's engine after the set number of moves.", "where": "Position, Studies: Up next, the category tiles with their progress (Basic mates, Mating patterns, Tactics, Endgames, Set-ups), a card for every study, and the Study card at the top while one runs.", "go": "position", "example": "Lucena position: White to move. Queen the pawn and keep the queen.", "see": ["coach", "lucena-position", "opposition", "hint"]}
];
if (typeof module !== 'undefined') module.exports = GRIMOIRE;
